INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l31',4,6,31,'The Sculptor Speaks','雕塑家说','as if / as though + 虚拟语气(as if he were holding it)、现在分词的完成式作状语(Having studied it, …)、现在分词作定语(a child learning to see)、比较级 + than(harder than … / many more … than)、whatever/whichever/however 引导让步(NCE4 无 KS 页,考点由课文结构自取;IP:源为雕塑家亨利·摩尔《The Sculptor Speaks》一文,是署名版权的第一人称艺术随笔——已用 100% 原创行文复述其‘欣赏雕塑须感知三维形体’的观点,无逐句改写、无具名;题材=艺术欣赏·无害;美语化 color/ladybug;第四册第31课·U6开工)','要欣赏雕塑,你必须能对三维的形体作出反应。这也许正是它常被称作一切艺术中最难者的原因——肯定比那些只需回应平面形体、二维形状的艺术更难。说实话,‘形盲’的人远比‘色盲’的多。一个初学看东西的孩子,起初只分辨得出二维形状;他还判断不了距离与深浅。后来,为了自身安全与实际需要,他才学会——部分靠触摸——粗略地判断三维的远近。可一旦这些实用需求得到满足,大多数人便不再深究。他们纵然能极准确地感知平面形体,却始终不肯再作那一步智力与情感上的努力,去把握形体在完整空间中的存在。而这,恰恰是雕塑家必须做的。他得不断地、把形体当作它完整的空间整体来思考。他仿佛把那实心的形状抓在自己脑袋里;无论它多大,他都仿佛正将它整个握在掌心。从各个角度端详过之后,他在心里把一个复杂的形体从四面八方立体地想象出来:看着这一面时,他已经知道另一面是什么样;他把自己代入它的重心、它的质量、它的重量;他感受它的体积,就像感受这形状在空气中所占据、所排开的那片空间。而一个敏感的雕塑观赏者,也必须学会做几分相似的事。他必须把形体单纯当作形体来感受,而不是当作对某物的描述或联想。比如,他得能把一枚鸡蛋看成一个纯粹、单一的实体——完全撇开它作为食物的意义,也撇开‘它有朝一日会变成一只鸟’的念头。对一颗坚果、一只梨、一只蝌蚪、一朵蘑菇、一根胡萝卜、一枚花苞,也是如此;从这些简单的实体出发,他便能进而去欣赏远为复杂的形体,乃至几种形体的组合。','{"q":"Listen and answer — What do you have to be able to do to appreciate sculpture?","options":["Respond to form in three dimensions","Judge colours accurately","Read about the artist''s life","Touch every statue"],"answer_index":0}'::jsonb,'{"title":"as if + 虚拟 / 现在分词完成式作状语 / 现在分词作定语 / 比较级 + than / whatever 让步","intro":"①as if / as though + 虚拟语气:与现在相反 be 用 were;与过去相反用 had + 过去分词。②现在分词的完成式 having + 过去分词,表动作发生在前:Having studied it, …。③现在分词作定语:a child learning to see。④比较级 + than;many more … than。⑤whatever/whichever/however 引导‘无论…’。","table":{"headers":["用法","结构","例子"],"rows":[["as if + 虚拟","as if + were / had done","as if he were holding it"],["现在分词完成式状语","Having + 过去分词, …","Having studied it, he carved"],["现在分词作定语","名词 + 现在分词","a child learning to see"],["比较级 + than","比较级 … than …","harder than flat art"],["whatever 让步","whatever / however + …","whatever its size"]]},"specialRules":[{"rule":"as if 从句表‘与事实相反’时用虚拟:现在用 were,过去用 had + 过去分词。","mark":"as if he were / had done"},{"rule":"however 后接形容词/副词(however hard);whatever/whichever 后接名词(whatever its size)。","mark":"however + 形容词"},{"rule":"美式拼写:color(颜色,英式 colour)、ladybug(瓢虫,英式 ladybird)。本课已按美语写。","mark":"color / ladybug"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l31',1,NULL,'To appreciate sculpture, you must be able to respond to form in three dimensions. That is perhaps why it is often called the most difficult of all the arts — certainly harder than those that ask only for a response to flat form, to shape in two dimensions. Many more people, in truth, are ''form-blind'' than colour-blind.','要欣赏雕塑,你必须能对三维的形体作出反应。这也许正是它常被称作一切艺术中最难者的原因——肯定比那些只需回应平面形体、二维形状的艺术更难。说实话,‘形盲’的人远比‘色盲’的多。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l31',2,NULL,'A child learning to see distinguishes at first only two-dimensional shape; it cannot yet judge distance or depth. Later, for the sake of its own safety and its practical needs, it learns — partly through touch — to judge three-dimensional distances roughly. But once these practical demands are met, most people go no further.','一个初学看东西的孩子,起初只分辨得出二维形状;他还判断不了距离与深浅。后来,为了自身安全与实际需要,他才学会——部分靠触摸——粗略地判断三维的远近。可一旦这些实用需求得到满足,大多数人便不再深究。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l31',3,NULL,'Though they may attain great accuracy in the perception of flat form, they never make the further intellectual and emotional effort needed to comprehend form in its full spatial existence. This is exactly what the sculptor must do. He has to think, continually, of form in its complete spatial wholeness.','他们纵然能极准确地感知平面形体,却始终不肯再作那一步智力与情感上的努力,去把握形体在完整空间中的存在。而这,恰恰是雕塑家必须做的。他得不断地、把形体当作它完整的空间整体来思考。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l31',4,NULL,'He grasps the solid shape, as it were, inside his own head; he thinks of it, whatever its size, as if he were holding it entirely enclosed in the hollow of his hand. Having studied it from every side, he visualizes a complex form all round itself: while he looks at one face he already knows what the other is like; he identifies himself with its centre of gravity, its mass, its weight; he feels its volume as the space that the shape displaces in the air.','他仿佛把那实心的形状抓在自己脑袋里;无论它多大,他都仿佛正将它整个握在掌心。从各个角度端详过之后,他在心里把一个复杂的形体从四面八方立体地想象出来:看着这一面时,他已经知道另一面是什么样;他把自己代入它的重心、它的质量、它的重量;他感受它的体积,就像感受这形状在空气中所排开的那片空间。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l31',5,NULL,'The sensitive observer of sculpture must learn to do something of the same. He must feel shape simply as shape, not as description or reminiscence. He must be able, for instance, to perceive an egg as a pure, single solid — quite apart from its use as food, or from the thought that it may one day become a bird. And so with a nut, a pear, a tadpole, a mushroom, a carrot, a bud: from such simple solids he can go on to appreciate far more complex forms.','而一个敏感的雕塑观赏者,也必须学会做几分相似的事。他必须把形体单纯当作形体来感受,而不是当作对某物的描述或联想。比如,他得能把一枚鸡蛋看成一个纯粹、单一的实体——完全撇开它作为食物的意义,也撇开‘它有朝一日会变成一只鸟’的念头。对一颗坚果、一只梨、一只蝌蚪、一朵蘑菇、一根胡萝卜、一枚花苞,也是如此;从这些简单的实体出发,他便能进而去欣赏远为复杂的形体。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
