INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l32','recognize','recognise','承认,认出;美语 recognize,英式 recognise') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l32','center','centre','中心;美语 center,英式 centre') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn) VALUES ('am4_l32','defense','defence','防御,辩护;美语 defense,英式 defence') ON CONFLICT (lesson_id,us) DO UPDATE SET uk=EXCLUDED.uk,note_cn=EXCLUDED.note_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l32','look through','',NULL,'/lʊk θruː/','Looking through his telescope, he saw the moon clearly.','透过望远镜,他清楚地看到了月亮。','She looked through the window at the rain.','她透过窗户望着雨。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l32','die with','',NULL,'/daɪ wɪð/','The ideas he defended did not die with him.','他捍卫的思想没有随他一同消亡。','The old customs died with the last villagers.','那些旧习俗随最后的村民一同消失了。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l32','prove true','',NULL,'/pruːv truː/','What he claimed has slowly been proven true.','他所主张的一切慢慢被证明为真。','In time, her warning proved true.','过了一段时间,她的警告被证明是对的。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l32','be honored as','',NULL,'/bi ˈɑːnərd æz/','He has since been honored as a founder of science.','他此后被尊崇为科学的奠基者之一。','She is honored as a hero in her hometown.','在家乡她被尊崇为英雄。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',5,'am4_l32_gp1','choice','{"stem":"\"For teaching the forbidden theory, Galileo ___ condemned by the Church.\"(一般过去的被动 be + 过去分词,填那个 be 动词的过去式)","options":["is","was","has","did"],"answer_index":1,"stem_cn":"因传授那个被禁的学说,伽利略被教会定罪。","explanation_cn":"一般过去的被动 = was/were + 过去分词;主语 Galileo 单数,填 was。✓ Galileo was condemned. ✗ is(现在)/ has(需接 been)/ did:一般过去被动用 was + 过去分词。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',5,'am4_l32_gp1','choice','{"stem":"\"Today Galileo ___ been honored as a founder of modern science.\"(现在完成的被动,填 been 前那个助动词)","options":["has","had","was","is"],"answer_index":0,"stem_cn":"如今伽利略被尊崇为现代科学的奠基者之一。","explanation_cn":"现在完成的被动 = has/have been + 过去分词;主语单数,填 has。✓ has been honored. ✗ was(一般过去)/ is / had(过去完成):现在完成用 has been done。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',5,'am4_l32_gp1','choice','{"stem":"\"What he claimed has now ___ proven true.\"(现在完成的被动 has + ___ + 过去分词,填 has 与过去分词之间那个词)","options":["be","being","been","was"],"answer_index":2,"stem_cn":"他所主张的东西如今已被证明为真。","explanation_cn":"现在完成的被动 has + been + 过去分词;填 has 与过去分词之间的 been。✓ has been proven true. ✗ being / be / was:has 之后用 been。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',5,'am4_l32_gp2','choice','{"stem":"\"He built a telescope ___ which he studied the distant stars.\"(‘介词 + 关系词’,‘用它’,填 which 前那个介词)","options":["with","for","of","in"],"answer_index":0,"stem_cn":"他造了一架望远镜,用它研究遥远的星辰。","explanation_cn":"‘介词 + 关系词’,‘用它研究’= with which;填 which 前的介词 with。✓ the telescope with which he studied. ✗ for / in / of:表‘用(工具)’用 with。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',5,'am4_l32_gp2','choice','{"stem":"\"It was a theory ___ the Church had forbidden.\"(限定性定语从句,先行词指物、在从句里作宾语,填关系词)","options":["who","that","what","whom"],"answer_index":1,"stem_cn":"这是一种教会曾禁止的学说。","explanation_cn":"限定性定语从句,先行词 theory 指物、在从句里作宾语,用 that。✓ a theory that the Church had forbidden. ✗ who/whom(指人)/ what(不引导定语从句)。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',5,'am4_l32_gp2','choice','{"stem":"\"Galileo, ___ name is known to every child, was once condemned.\"(非限定定语从句,表‘他的名字’,填关系词)","options":["whose","which","who","that"],"answer_index":0,"stem_cn":"伽利略——他的名字每个孩子都知道——曾被定罪。","explanation_cn":"非限定定语从句,表‘他的名字’这种所属关系,用 whose。✓ Galileo, whose name is known… ✗ who(作主语)/ which / that(that 不用于非限定):表所属用 whose。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',5,'am4_l32_gp3','choice','{"stem":"\"___ through his telescope, Galileo saw that the Earth moved.\"(现在分词作状语,表主动,填 look 的 -ing 形式)","options":["To look","Looking","Look","Looked"],"answer_index":1,"stem_cn":"透过望远镜观望,伽利略看到了地球在运动。","explanation_cn":"现在分词作状语,表主动(他在看);填 look 的 -ing 形式 Looking。✓ Looking through his telescope, he saw… ✗ Looked / Look / To look:主动的分词状语用现在分词。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',5,'am4_l32_gp3','choice','{"stem":"\"___ by the authorities, he spent his last years under arrest.\"(过去分词作状语,表被动‘被压制’,填 silence 的过去分词)","options":["Silencing","Silence","To silence","Silenced"],"answer_index":3,"stem_cn":"在当局的噤声之下,他在软禁中度过余生。","explanation_cn":"过去分词作状语,表被动(他被压制);填 silence 的过去分词 Silenced。✓ Silenced by the authorities, he… ✗ Silencing(主动)/ Silence / To silence:被动的分词状语用过去分词。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',5,'am4_l32_gp3','choice','{"stem":"\"His claim was confirmed by astronomers ___ centuries later.\"(现在分词作定语‘随后到来的’,填 come 的 -ing 形式)","options":["came","coming","to come","come"],"answer_index":1,"stem_cn":"他的主张由几个世纪后到来的天文学家所证实。","explanation_cn":"现在分词作后置定语,‘随后到来的天文学家’;填 come 的 -ing 形式 coming。✓ astronomers coming centuries later. ✗ came / come / to come:主动的后置定语用现在分词。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',5,'am4_l32_gp4','choice','{"stem":"\"He saw evidence ___ the Earth moved around the sun.\"(同位语从句,补充说明 evidence 的内容,填引导词)","options":["whether","which","what","that"],"answer_index":3,"stem_cn":"他看到了地球绕太阳运行的证据。","explanation_cn":"同位语从句,补充说明 evidence 的内容,用 that(从句完整不缺成分)。✓ evidence that the Earth moved. ✗ which / what(在从句里要作成分)/ whether(表‘是否’,意思不符)。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',5,'am4_l32_gp4','choice','{"stem":"\"___ he had claimed has now been proven true.\"(名词性从句作主语,从句里缺宾语‘所主张的东西’,填引导词)","options":["Whose","What","That","Which"],"answer_index":1,"stem_cn":"他所主张的东西如今已被证明为真。","explanation_cn":"名词性从句作主语,从句里缺宾语‘所主张的东西’,用 What。✓ What he had claimed has been proven. ✗ That(从句不缺成分才用)/ Which / Whose。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',5,'am4_l32_gp4','choice','{"stem":"\"It is now recognized ___ his courage changed science.\"(主语从句,补充说明被承认的事实,填引导词)","options":["whether","which","that","what"],"answer_index":2,"stem_cn":"如今人们承认,是他的勇气改变了科学。","explanation_cn":"主语从句,补充说明被承认的事实,用 that(陈述一个事实)。✓ It is recognized that his courage changed science. ✗ what(要作成分)/ which / whether(表‘是否’,意思不符)。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',5,'am4_l32_gp5','choice','{"stem":"\"It was a theory the Church ___ forbidden years before.\"(过去完成时,表‘更早之前早已禁止’,填助动词)","options":["had","has","was","did"],"answer_index":0,"stem_cn":"这是教会多年前早已禁止的一种学说。","explanation_cn":"过去完成时,表‘更早之前早已禁止’= had + 过去分词;填 had。✓ the Church had forbidden it years before. ✗ has(现在完成)/ was / did:‘过去的过去’用 had done。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',5,'am4_l32_gp5','choice','{"stem":"\"Over the centuries, what he claimed ___ been proven true.\"(现在完成的被动 ___ been + 过去分词,填助动词)","options":["was","is","had","has"],"answer_index":3,"stem_cn":"数百年间,他所主张的一切已被证明为真。","explanation_cn":"现在完成的被动 has + been + 过去分词;填助动词 has。✓ what he claimed has been proven true. ✗ had(过去完成)/ was(一般过去)/ is:现在完成用 has been done。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',5,'am4_l32_gp5','choice','{"stem":"\"The ideas that he had ___ did not die with him.\"(过去完成 had + 过去分词,填 defend 的过去分词)","options":["to defend","defended","defend","defending"],"answer_index":1,"stem_cn":"他曾捍卫的那些思想没有随他一同消亡。","explanation_cn":"过去完成 had + 过去分词;填 defend 的过去分词 defended。✓ the ideas that he had defended. ✗ defend / defending / to defend:had 之后用过去分词。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',5,'am4_l32_gp6','choice','{"stem":"\"To declare someone guilty and deserving of punishment is to ___ them.\"(“谴责,定罪”用哪个词)","options":["command","commend","condense","condemn"],"answer_index":3,"stem_cn":"宣布某人有罪、该受惩罚。","explanation_cn":"宣布某人有罪、该受惩罚是 condemn(谴责、定罪)。✓ he was condemned. ✗ command 命令;✗ commend 表扬;✗ condense 浓缩——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',5,'am4_l32_gp6','choice','{"stem":"\"To officially refuse to allow something is to ___ it.\"(“禁止”用哪个词)","options":["forge","afford","forbid","forecast"],"answer_index":2,"stem_cn":"正式地不允许某事。","explanation_cn":"正式地不允许某事是 forbid(禁止)。✓ a theory the Church had forbidden. ✗ afford 负担得起;✗ forecast 预报;✗ forge 伪造/锻造——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',5,'am4_l32_gp6','choice','{"stem":"\"The general opinion that people hold about someone is that person''s ___.\"(“声誉,名声”用哪个词)","options":["reservation","reputation","registration","recreation"],"answer_index":1,"stem_cn":"人们对某人普遍持有的看法。","explanation_cn":"人们对某人普遍持有的看法是 reputation(声誉、名声)。✓ his reputation ruined. ✗ recreation 娱乐;✗ reservation 预订;✗ registration 登记——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',6,NULL,'choice','{"stem":"astronomer 的意思是:","options":["天文学家","考古学家","地质学家","占星师"],"answer_index":0,"explanation_cn":"astronomer = 天文学家。✓ the astronomer whose name is known to every child."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',6,NULL,'choice','{"stem":"telescope 的意思是:","options":["温度计","万花筒","显微镜","望远镜"],"answer_index":3,"explanation_cn":"telescope = 望远镜。✓ a telescope with which he studied the stars."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',6,NULL,'choice','{"stem":"condemn 的意思是:","options":["谴责,定罪","忽视,无视","原谅,宽恕","赞扬,称赞"],"answer_index":0,"explanation_cn":"condemn = 谴责、定罪。✓ Galileo was condemned."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',6,NULL,'choice','{"stem":"evidence 的意思是:","options":["观点","秘密","谣言","证据"],"answer_index":3,"explanation_cn":"evidence = 证据。✓ he saw evidence that the Earth moved."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',6,NULL,'choice','{"stem":"recognize 的意思是:","options":["承认,认可","怀疑,质疑","否认,拒绝","忘记,遗忘"],"answer_index":0,"explanation_cn":"recognize = 承认、认可。✓ it is now recognized that…"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',6,NULL,'choice','{"stem":"universe 的意思是:","options":["国家","宇宙","城市","地球"],"answer_index":1,"explanation_cn":"universe = 宇宙。✓ how humanity understands the universe."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',7,NULL,'cloze','{"stem":"第 1 空","context":"Galileo built a telescope ___1___ which he studied the stars. He saw evidence ___2___ the Earth moved around the sun. For teaching this he ___3___ condemned by the Church. Yet what he had claimed has since ___4___ proven true, and today he is honored as a founder of science.","blank_no":1,"options":["with","for","in","of"],"answer_index":0,"explanation_cn":"‘介词 + 关系词’,‘用它’= with which;填 with。✓ a telescope with which he studied the stars."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',7,NULL,'cloze','{"stem":"第 2 空","context":"Galileo built a telescope ___1___ which he studied the stars. He saw evidence ___2___ the Earth moved around the sun. For teaching this he ___3___ condemned by the Church. Yet what he had claimed has since ___4___ proven true, and today he is honored as a founder of science.","blank_no":2,"options":["that","which","what","whether"],"answer_index":0,"explanation_cn":"同位语从句,补充说明 evidence 的内容,用 that。✓ evidence that the Earth moved."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',7,NULL,'cloze','{"stem":"第 3 空","context":"Galileo built a telescope ___1___ which he studied the stars. He saw evidence ___2___ the Earth moved around the sun. For teaching this he ___3___ condemned by the Church. Yet what he had claimed has since ___4___ proven true, and today he is honored as a founder of science.","blank_no":3,"options":["was","has","is","had"],"answer_index":0,"explanation_cn":"一般过去的被动 = was + 过去分词;填 was。✓ he was condemned by the Church."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',7,NULL,'cloze','{"stem":"第 4 空","context":"Galileo built a telescope ___1___ which he studied the stars. He saw evidence ___2___ the Earth moved around the sun. For teaching this he ___3___ condemned by the Church. Yet what he had claimed has since ___4___ proven true, and today he is honored as a founder of science.","blank_no":4,"options":["been","being","be","was"],"answer_index":0,"explanation_cn":"现在完成的被动 has + been + 过去分词;填 been。✓ has since been proven true."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',8,NULL,'choice','{"stem":"Why was Galileo condemned by the Church in his own lifetime?","options":["Because he taught the forbidden theory that the Earth moves around the sun","Because he could not find any stars","Because he refused to build a telescope","Because he agreed with everything the Church said"],"answer_index":0,"explanation_cn":"录音说:伽利略生前被定罪,是因为他传授了地球绕太阳运行这个被教会禁止的学说。✓ forbidden theory."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',8,NULL,'choice','{"stem":"According to the passage, what happened to Galileo''s ideas after his death?","options":["They were burned along with his books","They were proven false by later astronomers","They were completely forgotten forever","They did not die with him; over the centuries what he claimed has been proven true"],"answer_index":3,"explanation_cn":"录音说:伽利略的思想没有随他消亡,数百年间他所主张的一切被证明为真。✓ ideas survived."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',8,NULL,'choice','{"stem":"In what sense does the writer say Galileo has been ''reborn''?","options":["His son took over his exact work","He was literally brought back to life","The genius once silenced is now honored, his name standing for truth and the freedom to question","His house arrest was finally ended while he lived"],"answer_index":2,"explanation_cn":"录音说:那位曾被噤声的天才如今被尊崇,名字代表真理与质疑的自由,故谓‘复生’。✓ reborn = honored again."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',9,NULL,'choice','{"stem":"你想说\"伽利略因传授那个被禁止的学说而被定罪\"(被动语态):","options":["Galileo was condemned for teaching the forbidden theory.","Galileo condemned for teaching the forbidden theory.","Galileo was condemning for teaching the forbidden theory.","Galileo was condemn for teaching the forbidden theory."],"answer_index":0,"explanation_cn":"被动语态 was + 过去分词:be 动词用 was、后面用过去分词 condemned(不用原形 condemn、不用现在分词 condemning);不能漏掉 was。✓ was condemned. 场合:说“(某人)被……”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',9,NULL,'choice','{"stem":"你想说\"他造了一架用来研究星空的望远镜\"(介词 + 关系词 的定语从句):","options":["He built a telescope with which he studied the stars with.","He built a telescope with which he studied the stars.","He built a telescope which with he studied the stars.","He built a telescope with that he studied the stars."],"answer_index":1,"explanation_cn":"‘介词 + 关系词’要写成 with which(介词在前、关系词在后),不写成 which with、不用 with that;句尾不再重复 with。✓ with which he studied. 场合:说“用它来做某事(的那个东西)”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',9,NULL,'choice','{"stem":"你想说\"他所主张的东西如今已被证明是真的\"(名词性从句作主语 + 完成时被动):","options":["What he had claimed have now been proven true.","What he had claimed has now been proven truly.","What he had claimed has now been proven true.","That he had claimed has now been proven true."],"answer_index":2,"explanation_cn":"开头用 What 领起这句话(它在后半句里还要用到一次);中间的 has 用单数;结尾用 true 这个词(不用 truly)。✓ What he had claimed has been proven true. 场合:说“他所主张的……如今已被证明……”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',10,NULL,'choice','{"stem":"condemn 的意思是:","options":["忽视,无视","原谅,宽恕","赞扬,称赞","谴责,定罪"],"answer_index":3,"explanation_cn":"condemn = 谴责、定罪。✓ Galileo was condemned."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',10,NULL,'choice','{"stem":"universe 的意思是:","options":["海洋","宇宙","地球","国家"],"answer_index":1,"explanation_cn":"universe = 宇宙。✓ how humanity understands the universe."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',10,NULL,'choice','{"stem":"\"For teaching the forbidden theory, Galileo ___ condemned.\"(一般过去的被动)","options":["was","did","has","is"],"answer_index":0,"stem_cn":"因传授那个被禁的学说,伽利略被定罪。","explanation_cn":"一般过去的被动 = was + 过去分词;填 was。✓ Galileo was condemned. ✗ is / has / did。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',10,NULL,'choice','{"stem":"\"He built a telescope ___ which he studied the stars.\"(介词 + 关系词)","options":["in","of","with","for"],"answer_index":2,"stem_cn":"他造了一架用来研究星空的望远镜。","explanation_cn":"‘介词 + 关系词’,‘用它’= with which;填 with。✓ a telescope with which he studied the stars. ✗ for / in / of。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',10,NULL,'choice','{"stem":"\"be honored as\" 的意思是:","options":["被雇用为…","被尊崇为…","被误认为…","被指责为…"],"answer_index":1,"explanation_cn":"be honored as = 被尊崇为…。✓ honored as a founder of science."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',10,NULL,'choice','{"stem":"\"die with someone\" 的意思是:","options":["与某人同住","埋葬某人","随某人一同消亡","为某人而死"],"answer_index":2,"explanation_cn":"die with someone = 随某人一同消亡。✓ the ideas did not die with him."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',10,NULL,'choice','{"stem":"What did Galileo see when he looked through his telescope?","options":["That the sun moved around the Earth","That the stars were only a few miles away","Nothing at all worth recording","Evidence that the Earth moved around the sun"],"answer_index":3,"passage":"Few scientists have been as misunderstood in their own time as Galileo Galilei, the astronomer whose name is now known to every child. In the early seventeenth century, he built a telescope with which he studied the moon and the distant stars. Looking through it night after night, he saw evidence that the Earth moved around the sun. This was a theory that the Church had strictly forbidden, and for teaching it Galileo was condemned as a danger to the faith. Silenced by the authorities, he spent his final years under house arrest, his reputation ruined and his books banned. Yet the ideas that he had defended did not die with him. His discovery — that the Earth is only one small planet among many — was too important to be buried forever. Over the centuries, what he had claimed has slowly been proven true, confirmed by astronomers who came long after him. Though he was punished in his lifetime, he has since been honored as one of the founders of modern science. It is now recognized that his courage changed how humanity understands the universe. The genius who was once silenced has, in a very real sense, been reborn. Today his name stands not for shame but for truth, and the telescope he made has become a symbol of the freedom to question.","explanation_cn":"课文说:伽利略透过望远镜看到了地球绕太阳运行的证据。✓ evidence of a moving Earth."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',10,NULL,'choice','{"stem":"How does the writer say the world now regards Galileo, compared with his own time?","options":["He is completely forgotten by modern science","Once condemned and silenced, he is now honored as one of the founders of modern science","He is still condemned today just as he was then","He is remembered only as a maker of telescopes"],"answer_index":1,"passage":"Few scientists have been as misunderstood in their own time as Galileo Galilei, the astronomer whose name is now known to every child. In the early seventeenth century, he built a telescope with which he studied the moon and the distant stars. Looking through it night after night, he saw evidence that the Earth moved around the sun. This was a theory that the Church had strictly forbidden, and for teaching it Galileo was condemned as a danger to the faith. Silenced by the authorities, he spent his final years under house arrest, his reputation ruined and his books banned. Yet the ideas that he had defended did not die with him. His discovery — that the Earth is only one small planet among many — was too important to be buried forever. Over the centuries, what he had claimed has slowly been proven true, confirmed by astronomers who came long after him. Though he was punished in his lifetime, he has since been honored as one of the founders of modern science. It is now recognized that his courage changed how humanity understands the universe. The genius who was once silenced has, in a very real sense, been reborn. Today his name stands not for shame but for truth, and the telescope he made has become a symbol of the freedom to question.","explanation_cn":"课文说:伽利略生前被定罪、被噤声,如今却被尊崇为现代科学的奠基者之一。✓ condemned then, honored now."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',10,NULL,'choice','{"stem":"What had the Church done to the theory that the Earth moves before Galileo taught it?","options":["It had never heard of the theory","It had proven the theory true","It had strictly forbidden the theory","It had asked Galileo to teach it"],"answer_index":2,"audio":"Few scientists have been as misunderstood in their own time as Galileo Galilei, the astronomer whose name is now known to every child. In the early seventeenth century, he built a telescope with which he studied the moon and the distant stars. Looking through it night after night, he saw evidence that the Earth moved around the sun. This was a theory that the Church had strictly forbidden, and for teaching it Galileo was condemned as a danger to the faith. Silenced by the authorities, he spent his final years under house arrest, his reputation ruined and his books banned. Yet the ideas that he had defended did not die with him. His discovery — that the Earth is only one small planet among many — was too important to be buried forever. Over the centuries, what he had claimed has slowly been proven true, confirmed by astronomers who came long after him. Though he was punished in his lifetime, he has since been honored as one of the founders of modern science. It is now recognized that his courage changed how humanity understands the universe. The genius who was once silenced has, in a very real sense, been reborn. Today his name stands not for shame but for truth, and the telescope he made has become a symbol of the freedom to question.","explanation_cn":"课文说:在伽利略传授之前,教会早已严令禁止地球运动这一学说。✓ Church had forbidden it."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l32',10,NULL,'choice','{"stem":"According to the passage, what has slowly happened to what Galileo claimed?","options":["Over the centuries it has been proven true","It has been forgotten by everyone","It has been shown to be completely wrong","It has been kept secret to this day"],"answer_index":0,"audio":"Few scientists have been as misunderstood in their own time as Galileo Galilei, the astronomer whose name is now known to every child. In the early seventeenth century, he built a telescope with which he studied the moon and the distant stars. Looking through it night after night, he saw evidence that the Earth moved around the sun. This was a theory that the Church had strictly forbidden, and for teaching it Galileo was condemned as a danger to the faith. Silenced by the authorities, he spent his final years under house arrest, his reputation ruined and his books banned. Yet the ideas that he had defended did not die with him. His discovery — that the Earth is only one small planet among many — was too important to be buried forever. Over the centuries, what he had claimed has slowly been proven true, confirmed by astronomers who came long after him. Though he was punished in his lifetime, he has since been honored as one of the founders of modern science. It is now recognized that his courage changed how humanity understands the universe. The genius who was once silenced has, in a very real sense, been reborn. Today his name stands not for shame but for truth, and the telescope he made has become a symbol of the freedom to question.","explanation_cn":"课文说:数百年间,伽利略所主张的一切慢慢被证明为真。✓ proven true over time."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l34',4,6,34,'Adolescence','青春期','虚拟条件句(与现在相反:if + 过去式,主句 would + 动词原形)、too … to do(太…以致不能…)、使役动词 let/make sb do(接不带 to 的原形)、by + 动名词(方式状语)、know/believe sth to be …(不定式作宾语补足语)(NCE4 无 KS 页,考点由课文结构自取;IP:源为一篇《Journey Through Adolescence》里论‘青少年尊重肯认错的父母、幻灭不可免’的文章,无具名真实人物;通用心理/家庭观点用 100% 原创行文复述;题材=亲子心理·无害;美语化 behavior/humor;第四册第34课·跳过缺源的L32/L33)','青春期,对父母和年轻人都是一段难熬的日子。当孩子夸赞朋友家时,父母往往会受伤,把这话当成对自家饭菜、家务或家具的贬损——而且往往糊涂到让孩子看出自己在生气。他们甚至指责孩子不忠,或对朋友的家人说些刻薄话。这样丢了体面、又跌回孩子气的举止,只会把事情弄得更糟。不久,父母便抱怨孩子变得守口如瓶、什么都不说了;可他们很少意识到,这是自己招来的。对父母生出几分幻灭——无论他们作为父母、作为个人有多好多称职——都在某种程度上不可避免。多数孩子把父母的理想抬得太高,以至于除非父母确实很差劲,这理想几乎经不起现实的评判。父母若知道孩子通常对自己的品格与不会犯错抱有多深的信念、这份信任对孩子意味着什么,想必会大为惊讶、深受触动。父母若对这种青春期反应有所准备,并明白这是孩子在长大、在培养宝贵的观察力与独立判断力的信号,他们就不会那么受伤,也就不会因怨恨这反应而把孩子逼到对立面去。青少年怀着对真诚的热望,总是敬重一个肯承认自己有错、无知、甚至承认自己曾不公不义的父母。孩子无法原谅的,是当他明知那些指责属实时,父母却拒不承认。维多利亚时代的父母以为,躲在一副不讲道理的专制架子后面就能维持威严;其实根本不是那么回事,只不过当时的孩子被吓得太厉害,不敢让他们知道自己真实的感受罢了。如今我们又往另一个极端偏了,但总体而言,这对孩子和父母都是更健康的态度。无论当下多么难受,正视现实,永远都更明智、更稳妥。','{"q":"Listen and answer — What do adolescents respect in parents?","options":["A parent who admits when he is wrong, ignorant, or unfair","A parent who is always strict","A parent who never explains anything","A parent who gives them money"],"answer_index":0}'::jsonb,'{"title":"虚拟条件句 / too … to do / 使役 let·make sb do / by + 动名词 / know sth to be …","intro":"①与现在相反的虚拟条件:if + 过去式(be 用 were),主句 would + 动词原形。②too … to do,‘太…以致不能…’。③使役动词 let/make + sb + 动词原形(不加 to)。④by + 动名词,表方式:by retreating。⑤know/believe + sth + to be …(不定式作补足语)。","table":{"headers":["用法","结构","例子"],"rows":[["虚拟条件句","if + 过去式, would + 原形","if parents were prepared, they would not be hurt"],["too … to do","too + 形容词 + to do","too cowed to speak"],["使役 let/make","let/make + sb + 原形","let the youngsters see"],["by + 动名词","by + doing","by retreating behind an attitude"],["know sth to be","know/believe + sth + to be","knows them to be true"]]},"specialRules":[{"rule":"与现在事实相反的虚拟条件:if 从句 be 一律用 were,主句用 would + 动词原形。","mark":"if … were, would + 原形"},{"rule":"let/make + sb 后接不带 to 的动词原形;allow/ask/force + sb 则要接 to do。","mark":"let sb do(不加 to)"},{"rule":"美式拼写:behavior(行为,英式 behaviour)、humor(幽默,英式 humour)。本课已按美语写。","mark":"behavior / humor"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l34',1,NULL,'Adolescence is a difficult season for parents as much as for the young. Parents are often hurt when their children praise the homes of their friends, taking it as a slur on their own cooking, or housekeeping, or furniture — and they are often foolish enough to let the youngsters see that they are annoyed. They may even accuse them of disloyalty, or make some spiteful remark about the friends'' families.','青春期,对父母和年轻人都是一段难熬的日子。当孩子夸赞朋友家时,父母往往会受伤,把这话当成对自家饭菜、家务或家具的贬损——而且往往糊涂到让孩子看出自己在生气。他们甚至指责孩子不忠,或对朋友的家人说些刻薄话。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l34',2,NULL,'Such a loss of dignity, and such a descent into childish behavior, only makes things worse. Before long the parents are complaining that the child has grown secretive and tells them nothing; yet they seldom realize that they have brought this on themselves.','这样丢了体面、又跌回孩子气的举止,只会把事情弄得更糟。不久,父母便抱怨孩子变得守口如瓶、什么都不说了;可他们很少意识到,这是自己招来的。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l34',3,NULL,'Some disillusionment with one''s parents, however good and adequate they may be, is to some degree inevitable. Most children hold so high an ideal of their parents that, unless the parents have been genuinely unsatisfactory, it can hardly hope to stand up to a realistic evaluation. Parents would be greatly surprised, and deeply touched, if they realized how much belief their children usually place in their character and their infallibility.','对父母生出几分幻灭——无论他们作为父母、作为个人有多好多称职——都在某种程度上不可避免。多数孩子把父母的理想抬得太高,以至于除非父母确实很差劲,这理想几乎经不起现实的评判。父母若知道孩子通常对自己的品格与不会犯错抱有多深的信念,想必会大为惊讶、深受触动。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l34',4,NULL,'If parents were prepared for this adolescent reaction, and understood that it was a sign that the child was growing up and developing valuable powers of observation and independent judgment, they would not be so hurt, and so would not drive the child into opposition by resenting it. The adolescent, with his passion for sincerity, always respects a parent who admits that he is wrong, or ignorant, or even that he has been unfair or unjust.','父母若对这种青春期反应有所准备,并明白这是孩子在长大、在培养宝贵的观察力与独立判断力的信号,他们就不会那么受伤,也就不会因怨恨这反应而把孩子逼到对立面去。青少年怀着对真诚的热望,总是敬重一个肯承认自己有错、无知、甚至承认自己曾不公不义的父母。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l34',5,NULL,'What the child cannot forgive is the parent''s refusal to admit such charges when the child knows them to be true. Victorian parents believed that they kept their dignity by retreating behind an unreasoning, authoritarian attitude; in fact they did nothing of the kind, but their children were then too cowed to let them know how they really felt. It is always wiser, and safer, to face up to reality, however painful it may be at the moment.','孩子无法原谅的,是当他明知那些指责属实时,父母却拒不承认。维多利亚时代的父母以为,躲在一副不讲道理的专制架子后面就能维持威严;其实根本不是那么回事,只不过当时的孩子被吓得太厉害,不敢让他们知道自己真实的感受罢了。无论当下多么难受,正视现实,永远都更明智、更稳妥。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
