INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l34','stand up to','',NULL,'/stænd ʌp tuː/','The ideal cannot stand up to a realistic evaluation.','那理想经不起现实的评判。','He stood up to the bully.','他顶住了那个恶霸。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l34','bring on','',NULL,'/brɪŋ ɑːn/','They have brought this trouble on themselves.','这麻烦是他们自己招来的。','Stress can bring on a headache.','压力会引发头痛。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l34','face up to','',NULL,'/feɪs ʌp tuː/','It is wiser to face up to reality.','正视现实更为明智。','He must face up to his mistakes.','他必须正视自己的错误。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l34','to some degree','',NULL,'/tuː sʌm dɪˈɡriː/','Disillusionment is to some degree inevitable.','幻灭在某种程度上不可避免。','I agree with you, to some degree.','我在某种程度上同意你。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp1','choice','{"stem":"\"If parents ___ prepared for this reaction, they would not be so hurt.\"(与现在相反的虚拟条件,if 从句用 be 的虚拟形式)","options":["were","will be","are","was"],"answer_index":0,"stem_cn":"若父母对这种反应有所准备,就不会那么受伤。","explanation_cn":"与现在相反的虚拟条件,if 从句里 be 一律用 were。✓ If parents were prepared, … ✗ are / was / will be:虚拟条件 be 用 were。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp1','choice','{"stem":"\"If they realized the truth, they ___ be greatly touched.\"(与现在相反的虚拟,主句用‘助动词 + 动词原形’,填那个表‘将会’的情态词)","options":["may","will","can","would"],"answer_index":3,"stem_cn":"若他们明白真相,会深受感动。","explanation_cn":"与现在相反的虚拟,主句用 would + 动词原形;填 would。✓ they would be greatly touched. ✗ will(真实条件)/ can / may:虚拟主句用 would。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp1','choice','{"stem":"\"The child would talk more if the parents ___ less critical.\"(与现在相反的虚拟,if 从句用 be 的虚拟形式)","options":["will be","are","were","is"],"answer_index":2,"stem_cn":"若父母少些挑剔,孩子会多说些心里话。","explanation_cn":"与现在相反的虚拟条件,if 从句里 be 用 were。✓ if the parents were less critical. ✗ are / is / will be:虚拟条件 be 用 were。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp2','choice','{"stem":"\"The children were ___ cowed to say how they really felt.\"(‘太…以致不能…’,填 cowed 前那个词)","options":["quite","too","very","so"],"answer_index":1,"stem_cn":"孩子们被吓得太厉害,不敢说出真实感受。","explanation_cn":"‘太…以致不能…’= too + 形容词 + to do;填 too。✓ too cowed to say … ✗ so / very / quite:此结构用 too。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp2','choice','{"stem":"\"The parent was too proud ___ admit he was wrong.\"(too … 后接不定式,填不定式符号)","options":["at","of","to","for"],"answer_index":2,"stem_cn":"那位家长太要面子,不肯承认自己错了。","explanation_cn":"too … to do,后接不定式;填不定式符号 to。✓ too proud to admit he was wrong. ✗ for / at / of:不定式用 to。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp2','choice','{"stem":"\"He is too honest ___ hide his real feelings.\"(too … 后接不定式,填不定式符号)","options":["for","in","at","to"],"answer_index":3,"stem_cn":"他太诚实,藏不住真情实感。","explanation_cn":"too … to do,后接不定式;填不定式符号 to。✓ too honest to hide his feelings. ✗ for / at / in:不定式用 to。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp3','choice','{"stem":"\"Foolish parents ___ the adolescents see that they are annoyed.\"(使役动词,后接 sb + 动词原形(不加 to),‘让…看见’,填表‘让’的那个词)","options":["allow","force","let","want"],"answer_index":2,"stem_cn":"糊涂的父母让青少年看出自己在生气。","explanation_cn":"使役动词 let + sb + 动词原形(不加 to),‘让…看见’。✓ let the adolescents see … ✗ want / allow / force(都要接 to do):使役让某人做用 let。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp3','choice','{"stem":"\"Do not ___ the child feel that his friends'' homes are better.\"(使役动词,后接 sb + 动词原形(不加 to),‘使…感到’,填表‘使’的那个词)","options":["ask","force","tell","make"],"answer_index":3,"stem_cn":"别让孩子觉得朋友家更好。","explanation_cn":"使役动词 make + sb + 动词原形(不加 to),‘使…感到’。✓ make the child feel … ✗ tell / ask / force(都要接 to do):使役‘使’用 make。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp3','choice','{"stem":"\"A wise parent will ___ the child speak his mind freely.\"(使役动词,后接 sb + 动词原形(不加 to),‘让…说’,填表‘让’的那个词)","options":["get","permit","let","allow"],"answer_index":2,"stem_cn":"明智的父母会让孩子畅所欲言。","explanation_cn":"使役动词 let + sb + 动词原形(不加 to),‘让…说’。✓ let the child speak his mind. ✗ allow / permit / get(都要接 to do):使役‘让’用 let。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp4','choice','{"stem":"\"Victorian parents kept their dignity ___ retreating behind a strict attitude.\"(‘通过做…’= __ + 动名词,填那个表方式的介词)","options":["with","for","in","by"],"answer_index":3,"stem_cn":"维多利亚时代的父母靠端起严厉架子来维持威严。","explanation_cn":"‘通过做…’= by + 动名词;表方式的介词是 by。✓ by retreating behind an attitude. ✗ with / in / for:表方式‘通过’用 by。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp4','choice','{"stem":"\"You win a child''s trust ___ admitting your mistakes.\"(‘通过做…’= __ + 动名词,填那个表方式的介词)","options":["by","at","with","on"],"answer_index":0,"stem_cn":"靠承认自己的错误,你才能赢得孩子的信任。","explanation_cn":"‘通过做…’= by + 动名词;填 by。✓ by admitting your mistakes. ✗ with / on / at:表方式用 by。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp4','choice','{"stem":"\"By ___ up to reality, both sides are better off.\"(表方式的‘通过做…’结构,填‘面对’那个动词的动名词)","options":["faced","facing","to face","face"],"answer_index":1,"stem_cn":"靠正视现实,双方都更好过。","explanation_cn":"by + 动名词;填‘面对’那个动词的动名词 facing。✓ By facing up to reality. ✗ faced / face / to face:by 后用动名词。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp5','choice','{"stem":"\"The child knows these charges ___ be true.\"(know + sth + 不定式,‘知道…是…’,填不定式符号)","options":["that","being","to","as"],"answer_index":2,"stem_cn":"孩子知道这些指责是真的。","explanation_cn":"know + sth + 不定式,‘知道…是…’;填不定式符号 to。✓ knows these charges to be true. ✗ that / as / being:此结构用 to be。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp5','choice','{"stem":"\"Parents believe their own judgment ___ be always right.\"(believe + sth + 不定式,填不定式符号)","options":["to","that","being","as"],"answer_index":0,"stem_cn":"父母以为自己的判断总是对的。","explanation_cn":"believe + sth + 不定式;填不定式符号 to。✓ believe their judgment to be right. ✗ that / as / being:此结构用 to be。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp5','choice','{"stem":"\"We found the ideal ___ be far higher than most parents deserve.\"(find + sth + 不定式,填不定式符号)","options":["being","that","to","as"],"answer_index":2,"stem_cn":"我们发现那理想被抬得远高于多数父母配得上的。","explanation_cn":"find + sth + 不定式;填不定式符号 to。✓ found the ideal to be far higher than deserved. ✗ that / as / being:此结构用 to be。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp6','choice','{"stem":"\"A loss of one''s good opinion when reality falls short is ___.\"(“幻灭,理想破灭”用哪个词)","options":["entertainment","disillusionment","arrangement","advertisement"],"answer_index":1,"stem_cn":"当现实不及理想时失去的美好看法。","explanation_cn":"当现实不及理想时失去的美好看法是 disillusionment(幻灭)。✓ loss of one''s good opinion is disillusionment. ✗ entertainment 娱乐;✗ arrangement 安排;✗ advertisement 广告——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp6','choice','{"stem":"\"The quality of being honest and free from pretence is ___.\"(“真诚,诚挚”用哪个词)","options":["sincerity","authority","curiosity","majority"],"answer_index":0,"stem_cn":"诚实、不做作的品质。","explanation_cn":"诚实、不做作的品质是 sincerity(真诚)。✓ being honest and free from pretence is sincerity. ✗ curiosity 好奇;✗ authority 权威;✗ majority 多数——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',5,'am4_l34_gp6','choice','{"stem":"\"A slighting remark that harms someone''s reputation is a ___.\"(“诋毁,中伤”用哪个词)","options":["prize","gift","slur","cheer"],"answer_index":2,"stem_cn":"损害名声的贬损之词。","explanation_cn":"损害名声的贬损之词是 slur(诋毁、中伤)。✓ a slighting remark is a slur. ✗ cheer 欢呼;✗ prize 奖品;✗ gift 礼物——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',6,NULL,'choice','{"stem":"adolescence 的意思是:","options":["中年","青春期","童年","老年"],"answer_index":1,"explanation_cn":"adolescence = 青春期。✓ adolescence is a difficult season."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',6,NULL,'choice','{"stem":"disloyalty 的意思是:","options":["勇敢","忠诚","不忠,背叛","慷慨"],"answer_index":2,"explanation_cn":"disloyalty = 不忠、背叛。✓ accuse them of disloyalty."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',6,NULL,'choice','{"stem":"spiteful 的意思是:","options":["恶意的,怀恨的","友善的","慷慨的","耐心的"],"answer_index":0,"explanation_cn":"spiteful = 恶意的、怀恨的。✓ some spiteful remark."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',6,NULL,'choice','{"stem":"evaluation 的意思是:","options":["庆祝","命令","评价,评估","邀请"],"answer_index":2,"explanation_cn":"evaluation = 评价、评估。✓ a realistic evaluation."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',6,NULL,'choice','{"stem":"resent 的意思是:","options":["憎恨,怨恨","感激","原谅","欣赏"],"answer_index":0,"explanation_cn":"resent = 憎恨、怨恨。✓ into opposition by resenting it."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',6,NULL,'choice','{"stem":"authoritarian 的意思是:","options":["民主的","专制的,独裁的","随和的","宽容的"],"answer_index":1,"explanation_cn":"authoritarian = 专制的、独裁的。✓ an authoritarian attitude."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',7,NULL,'cloze','{"stem":"第 1 空","context":"If parents ___1___ prepared for this reaction, they would not be so hurt. A wise parent will ___2___ the child speak his mind. The child knows these charges ___3___ be true, and respects a parent who admits them. Both sides are better off ___4___ facing up to reality.","blank_no":1,"options":["were","are","was","will be"],"answer_index":0,"explanation_cn":"与现在相反的虚拟条件,if 从句 be 用 were。✓ If parents were prepared, they would not be so hurt."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',7,NULL,'cloze','{"stem":"第 2 空","context":"If parents ___1___ prepared for this reaction, they would not be so hurt. A wise parent will ___2___ the child speak his mind. The child knows these charges ___3___ be true, and respects a parent who admits them. Both sides are better off ___4___ facing up to reality.","blank_no":2,"options":["let","force","tell","ask"],"answer_index":0,"explanation_cn":"使役动词 let + sb + 动词原形。✓ a wise parent will let the child speak his mind."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',7,NULL,'cloze','{"stem":"第 3 空","context":"If parents ___1___ prepared for this reaction, they would not be so hurt. A wise parent will ___2___ the child speak his mind. The child knows these charges ___3___ be true, and respects a parent who admits them. Both sides are better off ___4___ facing up to reality.","blank_no":3,"options":["to","that","as","being"],"answer_index":0,"explanation_cn":"know + sth + 不定式,‘知道…是…’。✓ knows these charges to be true."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',7,NULL,'cloze','{"stem":"第 4 空","context":"If parents ___1___ prepared for this reaction, they would not be so hurt. A wise parent will ___2___ the child speak his mind. The child knows these charges ___3___ be true, and respects a parent who admits them. Both sides are better off ___4___ facing up to reality.","blank_no":4,"options":["by","with","in","for"],"answer_index":0,"explanation_cn":"by + 动名词,表方式。✓ better off by facing up to reality."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',8,NULL,'choice','{"stem":"What do adolescents respect in parents?","options":["A parent who admits when he is wrong, ignorant, or unfair","A parent who never explains anything","A parent who gives them money","A parent who is always strict"],"answer_index":0,"explanation_cn":"录音说:青少年敬重一个肯承认自己有错、无知或不公的父母。✓ admits when wrong."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',8,NULL,'choice','{"stem":"Why is some disillusionment with parents inevitable?","options":["Parents are always bad people","Children never loved their parents","Parents hide everything","Children hold so high an ideal of their parents that reality cannot match it"],"answer_index":3,"explanation_cn":"录音说:孩子把父母的理想抬得太高,现实几乎无法与之相称,故幻灭难免。✓ high ideal vs reality."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',8,NULL,'choice','{"stem":"What did Victorian parents wrongly believe kept their dignity?","options":["Admitting all their mistakes","Retreating behind an unreasoning, authoritarian attitude","Playing with their children","Giving in to every demand"],"answer_index":1,"explanation_cn":"录音说:维多利亚时代的父母误以为躲在专制架子后就能维持威严。✓ authoritarian retreat."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',9,NULL,'choice','{"stem":"你想说\"若父母对这种反应有所准备,就不会那么受伤\"(虚拟条件句):","options":["If parents are prepared for this reaction, they would not be so hurt.","If parents were prepared for this reaction, they will not be so hurt.","If parents was prepared for this reaction, they would not be so hurt.","If parents were prepared for this reaction, they would not be so hurt."],"answer_index":3,"explanation_cn":"与现在相反的虚拟条件:if 从句 be 用 were(不用 are/was)、主句用 would + 动词原形(不用 will)。✓ If … were …, … would … 场合:说“(与事实相反)若…就会…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',9,NULL,'choice','{"stem":"你想说\"孩子们被吓得太厉害,不敢说出真实感受\"(too … to do):","options":["The children were too cowed to say how they really felt.","The children were so cowed to say how they really felt.","The children were too cowed to saying how they really felt.","The children were too cowed that they could not say how they really felt."],"answer_index":0,"explanation_cn":"too + 形容词 + to do,‘太…以致不能…’;用 too … to do(不用 too … that、也不用 so … to)、to 后接原形 say(不写 saying)。✓ too cowed to say … 场合:说“太…以致做不了…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',9,NULL,'choice','{"stem":"你想说\"靠承认自己的错误,你才能赢得孩子的信任\"(by + 动名词):","options":["You win a child''s trust by admit your mistakes.","You win a child''s trust by admitting your mistakes.","You win a child''s trust with admitting your mistakes.","You win a child''s trust by to admit your mistakes."],"answer_index":1,"explanation_cn":"by + 动名词表方式;用 by(不用 with)、by 后接动名词 admitting(不写原形 admit、不写 to admit)。✓ by admitting … 场合:说“靠做…(来达成)”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',10,NULL,'choice','{"stem":"adolescence 的意思是:","options":["中年","童年","老年","青春期"],"answer_index":3,"explanation_cn":"adolescence = 青春期。✓ adolescence is a difficult season."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',10,NULL,'choice','{"stem":"resent 的意思是:","options":["憎恨,怨恨","欣赏","感激","原谅"],"answer_index":0,"explanation_cn":"resent = 憎恨、怨恨。✓ into opposition by resenting it."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',10,NULL,'choice','{"stem":"\"If parents ___ prepared for this reaction, they would not be so hurt.\"(与现在相反的虚拟条件,if 从句用 be 的虚拟形式)","options":["are","was","will be","were"],"answer_index":3,"stem_cn":"若父母对这种反应有所准备,就不会那么受伤。","explanation_cn":"与现在相反的虚拟条件,if 从句 be 用 were。✓ If parents were prepared … ✗ are / was / will be。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',10,NULL,'choice','{"stem":"\"The children were ___ cowed to say how they really felt.\"(‘太…以致不能…’,填 cowed 前那个词)","options":["quite","so","too","very"],"answer_index":2,"stem_cn":"孩子们被吓得太厉害,不敢说出真实感受。","explanation_cn":"‘太…以致不能…’用 too。✓ too cowed to say … ✗ so / very / quite。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',10,NULL,'choice','{"stem":"\"face up to\" 的意思是:","options":["忘记","勇敢面对,正视","推迟","逃避"],"answer_index":1,"explanation_cn":"face up to = 勇敢面对、正视。✓ face up to reality."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',10,NULL,'choice','{"stem":"\"stand up to\" 的意思是:","options":["坐下","服从","放弃","经得起,顶得住"],"answer_index":3,"explanation_cn":"stand up to = 经得起、顶得住。✓ cannot stand up to a realistic evaluation."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',10,NULL,'choice','{"stem":"According to the passage, what kind of parent does the adolescent respect?","options":["One who is coldly authoritarian","One who never talks to the child","One who admits when he is wrong, ignorant, or unfair","One who is always right in his own eyes"],"answer_index":2,"passage":"Adolescence is a difficult season for parents as much as for the young. Parents are often hurt when their children praise the homes of their friends, taking it as a slur on their own cooking, or housekeeping, or furniture — and they are often foolish enough to let the youngsters see that they are annoyed. They may even accuse them of disloyalty, or make some spiteful remark about the friends'' families. Such a loss of dignity, and such a descent into childish behavior, only makes things worse. Before long the parents are complaining that the child has grown secretive and tells them nothing; yet they seldom realize that they have brought this on themselves. Some disillusionment with one''s parents, however good and adequate they may be, is to some degree inevitable. Most children hold so high an ideal of their parents that, unless the parents have been genuinely unsatisfactory, it can hardly hope to stand up to a realistic evaluation. Parents would be greatly surprised, and deeply touched, if they realized how much belief their children usually place in their character and their infallibility, and how much this faith means to a child. If parents were prepared for this adolescent reaction, and understood that it was a sign that the child was growing up and developing valuable powers of observation and independent judgment, they would not be so hurt, and so would not drive the child into opposition by resenting it. The adolescent, with his passion for sincerity, always respects a parent who admits that he is wrong, or ignorant, or even that he has been unfair or unjust. What the child cannot forgive is the parent''s refusal to admit such charges when the child knows them to be true. Victorian parents believed that they kept their dignity by retreating behind an unreasoning, authoritarian attitude; in fact they did nothing of the kind, but their children were then too cowed to let them know how they really felt. Today we tend to go to the other extreme, but on the whole this is a healthier attitude for both the child and the parent. It is always wiser, and safer, to face up to reality, however painful it may be at the moment.","explanation_cn":"课文说:青少年敬重那种肯承认自己有错、无知或不公的父母。✓ admits fault."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',10,NULL,'choice','{"stem":"What can the adolescent not forgive?","options":["A parent who cooks badly","A parent''s refusal to admit charges the child knows to be true","A parent who says sorry","A parent who is sometimes tired"],"answer_index":1,"passage":"Adolescence is a difficult season for parents as much as for the young. Parents are often hurt when their children praise the homes of their friends, taking it as a slur on their own cooking, or housekeeping, or furniture — and they are often foolish enough to let the youngsters see that they are annoyed. They may even accuse them of disloyalty, or make some spiteful remark about the friends'' families. Such a loss of dignity, and such a descent into childish behavior, only makes things worse. Before long the parents are complaining that the child has grown secretive and tells them nothing; yet they seldom realize that they have brought this on themselves. Some disillusionment with one''s parents, however good and adequate they may be, is to some degree inevitable. Most children hold so high an ideal of their parents that, unless the parents have been genuinely unsatisfactory, it can hardly hope to stand up to a realistic evaluation. Parents would be greatly surprised, and deeply touched, if they realized how much belief their children usually place in their character and their infallibility, and how much this faith means to a child. If parents were prepared for this adolescent reaction, and understood that it was a sign that the child was growing up and developing valuable powers of observation and independent judgment, they would not be so hurt, and so would not drive the child into opposition by resenting it. The adolescent, with his passion for sincerity, always respects a parent who admits that he is wrong, or ignorant, or even that he has been unfair or unjust. What the child cannot forgive is the parent''s refusal to admit such charges when the child knows them to be true. Victorian parents believed that they kept their dignity by retreating behind an unreasoning, authoritarian attitude; in fact they did nothing of the kind, but their children were then too cowed to let them know how they really felt. Today we tend to go to the other extreme, but on the whole this is a healthier attitude for both the child and the parent. It is always wiser, and safer, to face up to reality, however painful it may be at the moment.","explanation_cn":"课文说:孩子无法原谅的,是明知指责属实、父母却拒不承认。✓ refusal to admit."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',10,NULL,'choice','{"stem":"Why should parents not be hurt by their child''s growing criticism?","options":["It is a sign of illness","It means the child hates them","It never really happens","It is a sign the child is developing observation and independent judgment"],"answer_index":3,"audio":"Adolescence is a difficult season for parents as much as for the young. Parents are often hurt when their children praise the homes of their friends, taking it as a slur on their own cooking, or housekeeping, or furniture — and they are often foolish enough to let the youngsters see that they are annoyed. They may even accuse them of disloyalty, or make some spiteful remark about the friends'' families. Such a loss of dignity, and such a descent into childish behavior, only makes things worse. Before long the parents are complaining that the child has grown secretive and tells them nothing; yet they seldom realize that they have brought this on themselves. Some disillusionment with one''s parents, however good and adequate they may be, is to some degree inevitable. Most children hold so high an ideal of their parents that, unless the parents have been genuinely unsatisfactory, it can hardly hope to stand up to a realistic evaluation. Parents would be greatly surprised, and deeply touched, if they realized how much belief their children usually place in their character and their infallibility, and how much this faith means to a child. If parents were prepared for this adolescent reaction, and understood that it was a sign that the child was growing up and developing valuable powers of observation and independent judgment, they would not be so hurt, and so would not drive the child into opposition by resenting it. The adolescent, with his passion for sincerity, always respects a parent who admits that he is wrong, or ignorant, or even that he has been unfair or unjust. What the child cannot forgive is the parent''s refusal to admit such charges when the child knows them to be true. Victorian parents believed that they kept their dignity by retreating behind an unreasoning, authoritarian attitude; in fact they did nothing of the kind, but their children were then too cowed to let them know how they really felt. Today we tend to go to the other extreme, but on the whole this is a healthier attitude for both the child and the parent. It is always wiser, and safer, to face up to reality, however painful it may be at the moment.","explanation_cn":"课文说:孩子的批评是他在长大、在培养观察力与独立判断力的信号,父母不必受伤。✓ sign of growing up."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l34',10,NULL,'choice','{"stem":"What is always wiser and safer, according to the speaker?","options":["To face up to reality, however painful it may be","To pretend to be perfect","To avoid the child","To hide behind authority"],"answer_index":0,"audio":"Adolescence is a difficult season for parents as much as for the young. Parents are often hurt when their children praise the homes of their friends, taking it as a slur on their own cooking, or housekeeping, or furniture — and they are often foolish enough to let the youngsters see that they are annoyed. They may even accuse them of disloyalty, or make some spiteful remark about the friends'' families. Such a loss of dignity, and such a descent into childish behavior, only makes things worse. Before long the parents are complaining that the child has grown secretive and tells them nothing; yet they seldom realize that they have brought this on themselves. Some disillusionment with one''s parents, however good and adequate they may be, is to some degree inevitable. Most children hold so high an ideal of their parents that, unless the parents have been genuinely unsatisfactory, it can hardly hope to stand up to a realistic evaluation. Parents would be greatly surprised, and deeply touched, if they realized how much belief their children usually place in their character and their infallibility, and how much this faith means to a child. If parents were prepared for this adolescent reaction, and understood that it was a sign that the child was growing up and developing valuable powers of observation and independent judgment, they would not be so hurt, and so would not drive the child into opposition by resenting it. The adolescent, with his passion for sincerity, always respects a parent who admits that he is wrong, or ignorant, or even that he has been unfair or unjust. What the child cannot forgive is the parent''s refusal to admit such charges when the child knows them to be true. Victorian parents believed that they kept their dignity by retreating behind an unreasoning, authoritarian attitude; in fact they did nothing of the kind, but their children were then too cowed to let them know how they really felt. Today we tend to go to the other extreme, but on the whole this is a healthier attitude for both the child and the parent. It is always wiser, and safer, to face up to reality, however painful it may be at the moment.","explanation_cn":"课文说:无论当下多难受,正视现实永远更明智、更稳妥。✓ face up to reality."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l35',4,6,35,'Space Odyssey','太空漫游','be likely / be able + to do、倍数表达(160 times more distant than / twice as tall as / a sixth of)、it takes + (精力/时间)+ to do、比较级 less/more … than、不定式作目的状语(To escape …, one must …)(NCE4 无 KS 页,考点由课文结构自取;IP:源为《7 Days》一篇论‘月球成太阳系工业枢纽、移民火星’的文章,内含真实人物阿瑟·C·克拉克的‘革命性想法三阶段’——已泛化为‘一位著名科幻作家’,通用天文/航天事实用 100% 原创行文复述;题材=太空科普·无害;美语化 colonize/program;第四册第35课)','月球很可能成为太阳系的工业枢纽:它可用从月岩里轻易提取的氧,为往来飞船供给燃料。原因在于它的引力。由于月球的质量只有地球的约十八分之一,从月球出发、飞越二十五万英里进入地球轨道,所需能量竟比从地球表面爬升区区两百英里还要少——少约百分之九十七。这听来匪夷所思,却极易算出。要靠火箭挣脱地球,你得达到每秒约七英里的速度;而从月球出发,对应的速度只有一点五英里。由于月球表面的引力仅为地球的六分之一,把飞船加速到那个更温和的速度,所耗能量远比在地球上少。简言之,月球居民飞入太空的花费,只相当于地球同类的百分之三。一位著名的科幻作家曾说,一个革命性的想法通常要经历三个阶段:先是‘不可能——别浪费我时间’;接着是‘可能,但不值得做’;最后是‘我一直就说这是个好主意’。移民火星——一个比月球还远一百六十倍的世界——这一想法,将在相当数量的人长期定居太空之时,决然地从第二阶段迈入第三阶段。火星对那些跃跃欲试的远航者有一种非凡的吸引力。美国、俄罗斯和欧洲满是热心人,其中不乏严肃的资深科学家,他们都梦想把人送上火星。这份心愿不难理解,因为它是太阳系里最像地球的那个世界。那里有红色的沙漠——故得旧名‘红色星球’——有万里无云的天空与骤起的沙暴,有远比大峡谷宽阔的裂谷,还有至少一座高逾珠峰两倍的山。总之,它似乎几乎是理想的定居之地。','{"q":"Listen and answer — When will it be possible for us to think seriously about colonizing Mars?","options":["When a significant number of people are living permanently in space","As soon as the Moon is reached","Never, in the author''s view","Only after Everest is climbed"],"answer_index":0}'::jsonb,'{"title":"be likely/able to do / 倍数表达 / it takes … to do / 比较级 less·more…than / 目的状语 to do","intro":"①be likely to do(很可能);be able to do(能够)。②倍数表达:160 times more distant than;twice as tall as;a sixth of。③it takes + 精力/时间 + to do。④比较级 less/more … than。⑤不定式作目的状语:To escape from the Earth, one must …。","table":{"headers":["用法","结构","例子"],"rows":[["be likely/able to do","be + 形容词 + to do","is likely to become the hub"],["倍数 + 比较级 + than","… times + 比较级 + than","160 times more distant than"],["倍数 + as … as","… times + as + 原级 + as","twice as tall as Everest"],["it takes … to do","it takes + 精力 + to do","it takes much less energy to accelerate"],["目的状语 to do","To do …, 主句","To escape, one must reach a speed"]]},"specialRules":[{"rule":"倍数放在比较结构最前面:… times + 比较级 + than;… times + as + 原级 + as。","mark":"倍数在最前"},{"rule":"less 修饰不可数(less energy);fewer 修饰可数(fewer ships);别混。","mark":"less energy / fewer ships"},{"rule":"美式拼写:colonize(殖民,英式 colonise)、program(计划,英式 programme)。本课已按美语写。","mark":"colonize / program"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l35',1,NULL,'The Moon is likely to become the industrial hub of the Solar System, supplying the fuel for its ships from oxygen easily extracted from the lunar rocks. The reason lies in its gravity. Because the Moon has only about an eighteenth of the Earth''s mass, it takes far less energy — some ninety-seven per cent less — to travel the quarter of a million miles from the Moon into Earth-orbit than to make the short two-hundred-mile climb from the Earth''s own surface.','月球很可能成为太阳系的工业枢纽:它可用从月岩里轻易提取的氧,为往来飞船供给燃料。原因在于它的引力。由于月球的质量只有地球的约十八分之一,从月球出发、飞越二十五万英里进入地球轨道,所需能量竟比从地球表面爬升区区两百英里还要少——少约百分之九十七。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l35',2,NULL,'This may sound fantastic, but it is easily worked out. To escape from the Earth in a rocket, one must reach a speed of about seven miles a second; the comparable speed from the Moon is only one and a half. Because the gravity at the Moon''s surface is only a sixth of the Earth''s, it takes much less energy to accelerate to that gentler speed than it does on Earth.','这听来匪夷所思,却极易算出。要靠火箭挣脱地球,你得达到每秒约七英里的速度;而从月球出发,对应的速度只有一点五英里。由于月球表面的引力仅为地球的六分之一,把飞船加速到那个更温和的速度,所耗能量远比在地球上少。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l35',3,NULL,'Moon-dwellers, in short, will be able to fly out into space at only three per cent of the cost paid by their terrestrial cousins. A well-known science-fiction writer once observed that a revolutionary idea usually passes through three phases: first, ''It''s impossible — don''t waste my time''; then, ''It''s possible, but not worth doing''; and at last, ''I said it was a good idea all along.''','简言之,月球居民飞入太空的花费,只相当于地球同类的百分之三。一位著名的科幻作家曾说,一个革命性的想法通常要经历三个阶段:先是‘不可能——别浪费我时间’;接着是‘可能,但不值得做’;最后是‘我一直就说这是个好主意’。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l35',4,NULL,'The idea of colonizing Mars — a world a hundred and sixty times more distant than the Moon — will move decisively from the second phase to the third when a significant number of people are living permanently in space. Mars holds an extraordinary fascination for would-be voyagers. America, Russia, and Europe are filled with enthusiasts, many of them serious and senior scientists, who dream of sending people there.','移民火星——一个比月球还远一百六十倍的世界——这一想法,将在相当数量的人长期定居太空之时,决然地从第二阶段迈入第三阶段。火星对那些跃跃欲试的远航者有一种非凡的吸引力。美国、俄罗斯和欧洲满是热心人,其中不乏严肃的资深科学家,他们都梦想把人送上火星。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l35',5,NULL,'Their aim is understandable, for it is the one world in the Solar System that is most like the Earth. It is a place of red sandy deserts — hence its old name, the Red Planet — of cloudless skies and sudden sandstorms, of chasms far wider than the Grand Canyon and at least one mountain more than twice as tall as Everest. It seems, in short, almost ideal for settlement.','这份心愿不难理解,因为它是太阳系里最像地球的那个世界。那里有红色的沙漠——故得旧名‘红色星球’——有万里无云的天空与骤起的沙暴,有远比大峡谷宽阔的裂谷,还有至少一座高逾珠峰两倍的山。总之,它似乎几乎是理想的定居之地。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_words (lesson_id,word,ipa,pos,meaning_cn,example) VALUES ('am4_l35','hub','/hʌb/','n','中心,枢纽','the industrial hub of the Solar System') ON CONFLICT (lesson_id,word) DO UPDATE SET ipa=EXCLUDED.ipa,pos=EXCLUDED.pos,meaning_cn=EXCLUDED.meaning_cn,example=EXCLUDED.example;
