INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l35','pass through','',NULL,'/pæs θruː/','A new idea passes through three phases.','一个新想法要经历三个阶段。','We passed through a small town at dawn.','拂晓时我们穿过一个小镇。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l35','be filled with','',NULL,'/biː fɪld wɪð/','Europe is filled with space enthusiasts.','欧洲满是太空热心人。','Her eyes were filled with tears.','她双眼含泪。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l35','lie in','',NULL,'/laɪ ɪn/','The reason lies in the Moon''s low gravity.','原因在于月球的低引力。','The answer lies in hard work.','答案在于努力。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l35','dream of','',NULL,'/driːm ʌv/','Scientists dream of colonizing Mars.','科学家梦想移民火星。','She dreams of becoming a pilot.','她梦想成为飞行员。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',5,'am4_l35_gp1','choice','{"stem":"\"The Moon is likely ___ become the industrial hub of space.\"(be likely + 不定式,‘很可能…’,填不定式符号)","options":["of","to","for","at"],"answer_index":1,"stem_cn":"月球很可能成为太空的工业枢纽。","explanation_cn":"be likely + 不定式,‘很可能…’;填不定式符号 to。✓ is likely to become the hub. ✗ for / at / of:不定式用 to。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',5,'am4_l35_gp1','choice','{"stem":"\"Moon-dwellers will be able ___ fly cheaply into space.\"(be able + 不定式,‘能够…’,填不定式符号)","options":["for","at","in","to"],"answer_index":3,"stem_cn":"月球居民将能廉价地飞入太空。","explanation_cn":"be able + 不定式,‘能够…’;填不定式符号 to。✓ will be able to fly cheaply. ✗ for / at / in:不定式用 to。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',5,'am4_l35_gp1','choice','{"stem":"\"Mars is ___ to attract many would-be settlers.\"(‘很可能…’= be __ to do,填那个表‘可能的’形容词)","options":["likeness","like","likely","alike"],"answer_index":2,"stem_cn":"火星很可能吸引许多想移居的人。","explanation_cn":"‘很可能…’= be + likely + to do;填形容词 likely。✓ Mars is likely to attract settlers. ✗ like(像)/ alike(相似的,作表语)/ likeness(名词):此处用 likely。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',5,'am4_l35_gp2','choice','{"stem":"\"Mars is 160 times more distant ___ the Moon.\"(倍数 + 比较级后接的那个连词)","options":["than","as","that","then"],"answer_index":0,"stem_cn":"火星比月球远160倍。","explanation_cn":"倍数 + 比较级(more distant)后接 than。✓ 160 times more distant than the Moon. ✗ as / that / then:比较级后用 than。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',5,'am4_l35_gp2','choice','{"stem":"\"Mars''s biggest chasm is many times ___ than the Grand Canyon.\"(倍数 + 比较级 + than,填‘宽’那个词的比较级形式)","options":["more wide","widest","wide","wider"],"answer_index":3,"stem_cn":"火星最大的裂谷比大峡谷宽好多倍。","explanation_cn":"倍数 + 比较级 + than;wide 是单音节形容词,比较级 wider。✓ many times wider than the Grand Canyon. ✗ widest(最高级)/ wide(原级)/ more wide:单音节用 -er。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',5,'am4_l35_gp2','choice','{"stem":"\"The Moon''s gravity is only a ___ of the Earth''s.\"(分数‘六分之一’,填序数词)","options":["sixth","six","sixty","sixteen"],"answer_index":0,"stem_cn":"月球引力只有地球的六分之一。","explanation_cn":"分数‘六分之一’,分母用序数词 sixth(a sixth of …)。✓ only a sixth of the Earth''s gravity. ✗ six / sixty / sixteen:分母用序数词 sixth。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',5,'am4_l35_gp3','choice','{"stem":"\"It ___ much less energy to accelerate on the Moon.\"(‘做…需要(花费)…’,填 it 后那个动词)","options":["gives","does","takes","makes"],"answer_index":2,"stem_cn":"在月球上加速所需的能量少得多。","explanation_cn":"‘做某事需要/花费…’用 it takes …;填动词 takes。✓ It takes much less energy to accelerate. ✗ makes / gives / does:‘花费/需要’用 takes。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',5,'am4_l35_gp3','choice','{"stem":"\"It takes less fuel ___ launch a rocket from the Moon.\"(it takes + 名词 + 不定式,填不定式符号)","options":["of","to","for","at"],"answer_index":1,"stem_cn":"从月球发射火箭所需燃料更少。","explanation_cn":"it takes + 名词 + 不定式;填不定式符号 to。✓ It takes less fuel to launch a rocket. ✗ for / at / of:不定式用 to。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',5,'am4_l35_gp3','choice','{"stem":"\"It would take enormous energy ___ escape from the Earth.\"(it takes/would take + 不定式,填不定式符号)","options":["to","for","at","in"],"answer_index":0,"stem_cn":"要脱离地球引力,得花巨大的能量。","explanation_cn":"it takes/would take + 不定式;填不定式符号 to。✓ It would take enormous energy to escape. ✗ for / at / in:不定式用 to。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',5,'am4_l35_gp4','choice','{"stem":"\"Launching from the Moon needs far ___ energy than from Earth.\"(‘更少的’能量,修饰不可数名词,填 energy 前那个词)","options":["fewer","less","little","few"],"answer_index":1,"stem_cn":"从月球发射所需能量远少于从地球。","explanation_cn":"‘更少的’能量,energy 不可数,用 less。✓ far less energy than from Earth. ✗ fewer(修饰可数)/ little(原级)/ few:修饰不可数用 less。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',5,'am4_l35_gp4','choice','{"stem":"\"Mars is much ___ distant than the Moon.\"(‘更远’,distant 的比较级)","options":["much","very","most","more"],"answer_index":3,"stem_cn":"火星比月球远得多。","explanation_cn":"distant 是多音节形容词,比较级前面加 more。✓ much more distant than the Moon. ✗ most(最高级)/ very / much:多音节比较级用 more。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',5,'am4_l35_gp4','choice','{"stem":"\"A journey from the Moon costs ___ than one from Earth.\"(‘更少’,little 的比较级,修饰动词 costs)","options":["fewer","least","less","lesser"],"answer_index":2,"stem_cn":"从月球出发的旅程比从地球出发花费更少。","explanation_cn":"‘更少’修饰动词 costs,用 little 的比较级 less。✓ costs less than one from Earth. ✗ least(最高级)/ fewer / lesser:此处用 less。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',5,'am4_l35_gp5','choice','{"stem":"\"___ escape from the Earth, one must travel at seven miles a second.\"(不定式作目的状语置于句首,‘为了逃离’,填不定式符号)","options":["For","Of","At","To"],"answer_index":3,"stem_cn":"要脱离地球,须以每秒七英里的速度飞行。","explanation_cn":"不定式作目的状语,置于句首,‘为了逃离’;填不定式符号 To。✓ To escape from the Earth, one must … ✗ For / At / Of:目的状语用 To do。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',5,'am4_l35_gp5','choice','{"stem":"\"Rockets carry lunar fuel ___ reach distant planets.\"(不定式作目的状语,‘为了到达’,填不定式符号)","options":["in","to","at","for"],"answer_index":1,"stem_cn":"火箭携带月球燃料,以抵达遥远的行星。","explanation_cn":"不定式作目的状语,‘为了到达’;填不定式符号 to。✓ carry fuel to reach distant planets. ✗ for / at / in:目的状语用 to。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',5,'am4_l35_gp5','choice','{"stem":"\"Scientists dream of colonies ___ study Mars up close.\"(不定式作目的状语,‘为了研究’,填不定式符号)","options":["for","at","to","of"],"answer_index":2,"stem_cn":"科学家梦想建立殖民地,以近距离研究火星。","explanation_cn":"不定式作目的状语,‘为了研究’;填不定式符号 to。✓ colonies to study Mars up close. ✗ for / at / of:目的状语用 to。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',5,'am4_l35_gp6','choice','{"stem":"\"A center of activity around which everything turns is a ___.\"(“中心,枢纽”用哪个词)","options":["edge","corner","border","hub"],"answer_index":3,"stem_cn":"一切围之运转的活动中心。","explanation_cn":"一切围之运转的活动中心是 hub(中心、枢纽)。✓ a center of activity is a hub. ✗ edge 边缘;✗ corner 角落;✗ border 边界——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',5,'am4_l35_gp6','choice','{"stem":"\"A deep crack or opening in a surface is a ___.\"(“裂口,深渊”用哪个词)","options":["hill","chasm","meadow","shore"],"answer_index":1,"stem_cn":"地表又深又大的裂口。","explanation_cn":"地表又深又大的裂口是 chasm(裂口、深渊)。✓ a deep crack in a surface is a chasm. ✗ hill 小山;✗ meadow 草地;✗ shore 岸——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',5,'am4_l35_gp6','choice','{"stem":"\"The word meaning ''relating to the moon'' is ___.\"(“月球的”用哪个词)","options":["stellar","polar","lunar","solar"],"answer_index":2,"stem_cn":"与月球有关的。","explanation_cn":"‘与月球有关的’是 lunar(月球的)。✓ relating to the moon is lunar. ✗ solar 太阳的;✗ polar 极地的;✗ stellar 恒星的——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',6,NULL,'choice','{"stem":"hub 的意思是:","options":["角落","中心,枢纽","边界","边缘"],"answer_index":1,"explanation_cn":"hub = 中心、枢纽。✓ the industrial hub of the Solar System."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',6,NULL,'choice','{"stem":"lunar 的意思是:","options":["地球的","太阳的","月球的","恒星的"],"answer_index":2,"explanation_cn":"lunar = 月球的。✓ extracted from the lunar rocks."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',6,NULL,'choice','{"stem":"accelerate 的意思是:","options":["停止","减速","转向","加速"],"answer_index":3,"explanation_cn":"accelerate = 加速。✓ energy to accelerate to that speed."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',6,NULL,'choice','{"stem":"terrestrial 的意思是:","options":["海洋的","月球的","陆地的,地球的","天空的"],"answer_index":2,"explanation_cn":"terrestrial = 陆地的、地球的。✓ their terrestrial cousins."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',6,NULL,'choice','{"stem":"fascination 的意思是:","options":["冷漠","恐惧","厌恶","迷恋,魅力"],"answer_index":3,"explanation_cn":"fascination = 迷恋、魅力。✓ an extraordinary fascination."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',6,NULL,'choice','{"stem":"chasm 的意思是:","options":["平原","山峰","裂口,深渊","海岸"],"answer_index":2,"explanation_cn":"chasm = 裂口、深渊。✓ chasms wider than the Grand Canyon."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',7,NULL,'cloze','{"stem":"第 1 空","context":"The Moon is ___1___ to become the industrial hub of space. Because its gravity is low, it ___2___ much less energy to launch a rocket there than on Earth. ___3___ escape from the Earth, one must travel at seven miles a second. Mars, 160 times more distant ___4___ the Moon, may one day be colonized.","blank_no":1,"options":["likely","like","alike","likeness"],"answer_index":0,"explanation_cn":"‘很可能…’= be likely to do;填 likely。✓ The Moon is likely to become the hub."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',7,NULL,'cloze','{"stem":"第 2 空","context":"The Moon is ___1___ to become the industrial hub of space. Because its gravity is low, it ___2___ much less energy to launch a rocket there than on Earth. ___3___ escape from the Earth, one must travel at seven miles a second. Mars, 160 times more distant ___4___ the Moon, may one day be colonized.","blank_no":2,"options":["takes","makes","gives","does"],"answer_index":0,"explanation_cn":"‘做某事需要/花费…’用 it takes;填 takes。✓ it takes much less energy to launch."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',7,NULL,'cloze','{"stem":"第 3 空","context":"The Moon is ___1___ to become the industrial hub of space. Because its gravity is low, it ___2___ much less energy to launch a rocket there than on Earth. ___3___ escape from the Earth, one must travel at seven miles a second. Mars, 160 times more distant ___4___ the Moon, may one day be colonized.","blank_no":3,"options":["To","For","At","Of"],"answer_index":0,"explanation_cn":"不定式作目的状语,置于句首;填 To。✓ To escape from the Earth, one must travel …"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',7,NULL,'cloze','{"stem":"第 4 空","context":"The Moon is ___1___ to become the industrial hub of space. Because its gravity is low, it ___2___ much less energy to launch a rocket there than on Earth. ___3___ escape from the Earth, one must travel at seven miles a second. Mars, 160 times more distant ___4___ the Moon, may one day be colonized.","blank_no":4,"options":["than","as","that","then"],"answer_index":0,"explanation_cn":"倍数 + 比较级后接 than。✓ 160 times more distant than the Moon."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',8,NULL,'choice','{"stem":"When will colonizing Mars move to the ''good idea'' phase?","options":["Never, in the author''s view","As soon as the Moon is reached","When a significant number of people are living permanently in space","Only after Everest is climbed"],"answer_index":2,"explanation_cn":"录音说:移民火星要等到相当多的人长期定居太空时,才会真正进入‘好主意’阶段。✓ people living permanently in space."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',8,NULL,'choice','{"stem":"Why is the Moon likely to become the industrial hub of the Solar System?","options":["It has more people than Earth","It is made of metal","It is closer to the Sun","Its low gravity makes launching ships far cheaper in energy"],"answer_index":3,"explanation_cn":"录音说:月球引力低,从月球发射飞船所耗能量远少于地球,故可能成为工业枢纽。✓ low gravity, cheaper launch."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',8,NULL,'choice','{"stem":"Why does Mars fascinate would-be voyagers?","options":["It is the world in the Solar System most like the Earth","It is the nearest planet","It is made of gold","It has no gravity"],"answer_index":0,"explanation_cn":"录音说:火星最像地球,所以吸引远航者。✓ most like the Earth."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',9,NULL,'choice','{"stem":"你想说\"月球很可能成为太空的工业枢纽\"(be likely to do):","options":["The Moon is likely become the industrial hub of space.","The Moon is likely to becoming the industrial hub of space.","The Moon is likely to become the industrial hub of space.","The Moon likely is to become the industrial hub of space."],"answer_index":2,"explanation_cn":"be likely to do,‘很可能…’;likely 后接 to + 动词原形 become(不省 to、不写 becoming)、语序为 is likely(不写 likely is)。✓ is likely to become … 场合:说“很可能会…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',9,NULL,'choice','{"stem":"你想说\"火星比月球远160倍\"(倍数 + 比较级 + than):","options":["Mars is 160 time more distant than the Moon.","Mars is 160 times more distant as the Moon.","Mars is more distant 160 times than the Moon.","Mars is 160 times more distant than the Moon."],"answer_index":3,"explanation_cn":"倍数放最前:160 times + 比较级 more distant + than;用 than(不用 as)、time 要用复数 times、倍数紧接在比较级前(不写 more distant 160 times)。✓ 160 times more distant than … 场合:说“比…(多少)倍”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',9,NULL,'choice','{"stem":"你想说\"在月球上加速所需的能量少得多\"(it takes … to do):","options":["There takes much less energy to accelerate on the Moon.","It takes much less energy to accelerate on the Moon.","It takes much less energy accelerating on the Moon.","It takes much less energy to accelerating on the Moon."],"answer_index":1,"explanation_cn":"it takes + 精力 + to do;句首用 It(不用 There)、to 后接原形 accelerate(不写 accelerating、也不写 to accelerating)。✓ It takes … energy to accelerate … 场合:说“做…需要(花费)…”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',10,NULL,'choice','{"stem":"hub 的意思是:","options":["边界","边缘","角落","中心,枢纽"],"answer_index":3,"explanation_cn":"hub = 中心、枢纽。✓ the industrial hub of the Solar System."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',10,NULL,'choice','{"stem":"lunar 的意思是:","options":["恒星的","月球的","地球的","太阳的"],"answer_index":1,"explanation_cn":"lunar = 月球的。✓ extracted from the lunar rocks."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',10,NULL,'choice','{"stem":"\"The Moon is ___ to become the industrial hub of space.\"(be … to do,‘很可能…’,填形容词)","options":["likeness","like","likely","alike"],"answer_index":2,"stem_cn":"月球很可能成为太空的工业枢纽。","explanation_cn":"‘很可能…’= be likely to do;填 likely。✓ is likely to become the hub. ✗ like / alike / likeness。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',10,NULL,'choice','{"stem":"\"Mars is 160 times more distant ___ the Moon.\"(倍数 + 比较级后接的连词)","options":["that","then","as","than"],"answer_index":3,"stem_cn":"火星比月球远160倍。","explanation_cn":"倍数 + 比较级后接 than。✓ 160 times more distant than the Moon. ✗ as / that / then。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',10,NULL,'choice','{"stem":"\"be filled with\" 的意思是:","options":["充满…","摆脱…","忽视…","缺少…"],"answer_index":0,"explanation_cn":"be filled with = 充满…。✓ Europe is filled with space enthusiasts."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',10,NULL,'choice','{"stem":"\"dream of\" 的意思是:","options":["忘记","拒绝","梦想,渴望","害怕"],"answer_index":2,"explanation_cn":"dream of = 梦想、渴望。✓ scientists dream of colonizing Mars."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',10,NULL,'choice','{"stem":"Why will the Moon become the industrial hub of the Solar System?","options":["Its weak gravity makes launching ships far cheaper in energy","It is the closest body to the Sun","It is bigger than the Earth","It already has cities"],"answer_index":0,"passage":"The Moon is likely to become the industrial hub of the Solar System, supplying the fuel for its ships from oxygen easily extracted from the lunar rocks. The reason lies in its gravity. Because the Moon has only about an eighteenth of the Earth''s mass, it takes far less energy — some ninety-seven per cent less — to travel the quarter of a million miles from the Moon into Earth-orbit than to make the short two-hundred-mile climb from the Earth''s own surface. This may sound fantastic, but it is easily worked out. To escape from the Earth in a rocket, one must reach a speed of about seven miles a second; the comparable speed from the Moon is only one and a half. Because the gravity at the Moon''s surface is only a sixth of the Earth''s, it takes much less energy to accelerate to that gentler speed than it does on Earth. Moon-dwellers, in short, will be able to fly out into space at only three per cent of the cost paid by their terrestrial cousins. A well-known science-fiction writer once observed that a revolutionary idea usually passes through three phases: first, ''It''s impossible — don''t waste my time''; then, ''It''s possible, but not worth doing''; and at last, ''I said it was a good idea all along.'' The idea of colonizing Mars — a world a hundred and sixty times more distant than the Moon — will move decisively from the second phase to the third when a significant number of people are living permanently in space. Mars holds an extraordinary fascination for would-be voyagers. America, Russia, and Europe are filled with enthusiasts, many of them serious and senior scientists, who dream of sending people there. Their aim is understandable, for it is the one world in the Solar System that is most like the Earth. It is a place of red sandy deserts — hence its old name, the Red Planet — of cloudless skies and sudden sandstorms, of chasms far wider than the Grand Canyon and at least one mountain more than twice as tall as Everest. It seems, in short, almost ideal for settlement.","explanation_cn":"课文说:月球引力弱,发射飞船所耗能量远少于地球,故将成工业枢纽。✓ weak gravity, cheaper launch."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',10,NULL,'choice','{"stem":"According to the passage, why does Mars seem ideal for settlement?","options":["It has a breathable atmosphere already","It is warmer than the Earth","It is the world most like the Earth, with skies, deserts, and mountains","It is covered in water"],"answer_index":2,"passage":"The Moon is likely to become the industrial hub of the Solar System, supplying the fuel for its ships from oxygen easily extracted from the lunar rocks. The reason lies in its gravity. Because the Moon has only about an eighteenth of the Earth''s mass, it takes far less energy — some ninety-seven per cent less — to travel the quarter of a million miles from the Moon into Earth-orbit than to make the short two-hundred-mile climb from the Earth''s own surface. This may sound fantastic, but it is easily worked out. To escape from the Earth in a rocket, one must reach a speed of about seven miles a second; the comparable speed from the Moon is only one and a half. Because the gravity at the Moon''s surface is only a sixth of the Earth''s, it takes much less energy to accelerate to that gentler speed than it does on Earth. Moon-dwellers, in short, will be able to fly out into space at only three per cent of the cost paid by their terrestrial cousins. A well-known science-fiction writer once observed that a revolutionary idea usually passes through three phases: first, ''It''s impossible — don''t waste my time''; then, ''It''s possible, but not worth doing''; and at last, ''I said it was a good idea all along.'' The idea of colonizing Mars — a world a hundred and sixty times more distant than the Moon — will move decisively from the second phase to the third when a significant number of people are living permanently in space. Mars holds an extraordinary fascination for would-be voyagers. America, Russia, and Europe are filled with enthusiasts, many of them serious and senior scientists, who dream of sending people there. Their aim is understandable, for it is the one world in the Solar System that is most like the Earth. It is a place of red sandy deserts — hence its old name, the Red Planet — of cloudless skies and sudden sandstorms, of chasms far wider than the Grand Canyon and at least one mountain more than twice as tall as Everest. It seems, in short, almost ideal for settlement.","explanation_cn":"课文说:火星是太阳系里最像地球的世界,有天空、沙漠与高山,似乎理想。✓ most like Earth."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',10,NULL,'choice','{"stem":"What must happen before colonizing Mars becomes a ''good idea''?","options":["Everest must be climbed","Many people must be living permanently in space","Rockets must stop using fuel","The Moon must be destroyed"],"answer_index":1,"audio":"The Moon is likely to become the industrial hub of the Solar System, supplying the fuel for its ships from oxygen easily extracted from the lunar rocks. The reason lies in its gravity. Because the Moon has only about an eighteenth of the Earth''s mass, it takes far less energy — some ninety-seven per cent less — to travel the quarter of a million miles from the Moon into Earth-orbit than to make the short two-hundred-mile climb from the Earth''s own surface. This may sound fantastic, but it is easily worked out. To escape from the Earth in a rocket, one must reach a speed of about seven miles a second; the comparable speed from the Moon is only one and a half. Because the gravity at the Moon''s surface is only a sixth of the Earth''s, it takes much less energy to accelerate to that gentler speed than it does on Earth. Moon-dwellers, in short, will be able to fly out into space at only three per cent of the cost paid by their terrestrial cousins. A well-known science-fiction writer once observed that a revolutionary idea usually passes through three phases: first, ''It''s impossible — don''t waste my time''; then, ''It''s possible, but not worth doing''; and at last, ''I said it was a good idea all along.'' The idea of colonizing Mars — a world a hundred and sixty times more distant than the Moon — will move decisively from the second phase to the third when a significant number of people are living permanently in space. Mars holds an extraordinary fascination for would-be voyagers. America, Russia, and Europe are filled with enthusiasts, many of them serious and senior scientists, who dream of sending people there. Their aim is understandable, for it is the one world in the Solar System that is most like the Earth. It is a place of red sandy deserts — hence its old name, the Red Planet — of cloudless skies and sudden sandstorms, of chasms far wider than the Grand Canyon and at least one mountain more than twice as tall as Everest. It seems, in short, almost ideal for settlement.","explanation_cn":"课文说:要到相当多的人长期定居太空,移民火星才成‘好主意’。✓ people permanently in space."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l35',10,NULL,'choice','{"stem":"How much of the usual cost will Moon-dwellers pay to fly in space?","options":["About three per cent of the cost of similar journeys from Earth","Nothing at all","The same as people on Earth","Twice as much as on Earth"],"answer_index":0,"audio":"The Moon is likely to become the industrial hub of the Solar System, supplying the fuel for its ships from oxygen easily extracted from the lunar rocks. The reason lies in its gravity. Because the Moon has only about an eighteenth of the Earth''s mass, it takes far less energy — some ninety-seven per cent less — to travel the quarter of a million miles from the Moon into Earth-orbit than to make the short two-hundred-mile climb from the Earth''s own surface. This may sound fantastic, but it is easily worked out. To escape from the Earth in a rocket, one must reach a speed of about seven miles a second; the comparable speed from the Moon is only one and a half. Because the gravity at the Moon''s surface is only a sixth of the Earth''s, it takes much less energy to accelerate to that gentler speed than it does on Earth. Moon-dwellers, in short, will be able to fly out into space at only three per cent of the cost paid by their terrestrial cousins. A well-known science-fiction writer once observed that a revolutionary idea usually passes through three phases: first, ''It''s impossible — don''t waste my time''; then, ''It''s possible, but not worth doing''; and at last, ''I said it was a good idea all along.'' The idea of colonizing Mars — a world a hundred and sixty times more distant than the Moon — will move decisively from the second phase to the third when a significant number of people are living permanently in space. Mars holds an extraordinary fascination for would-be voyagers. America, Russia, and Europe are filled with enthusiasts, many of them serious and senior scientists, who dream of sending people there. Their aim is understandable, for it is the one world in the Solar System that is most like the Earth. It is a place of red sandy deserts — hence its old name, the Red Planet — of cloudless skies and sudden sandstorms, of chasms far wider than the Grand Canyon and at least one mountain more than twice as tall as Everest. It seems, in short, almost ideal for settlement.","explanation_cn":"课文说:月球居民飞入太空的花费,只相当于地球同类的约百分之三。✓ three per cent of cost."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_lessons (id,book_no,unit_no,lesson_no,title_en,title_cn,grammar_focus,scene,prelisten_question,grammar_card) VALUES ('am4_l36',4,6,36,'The Cost of Government','政府的开支','As … , so …(随着…,…也随之…)、trust/rely on sb to do(相信/指望某人做某事)、to the extent that …(在…的程度上/只要)、can/could + be + 过去分词(情态与被动连用)、Where 引导从句(凡…之处)(NCE4 无 KS 页,考点由课文结构自取;IP:源为雷蒙德·弗罗斯特《The Backward Society》一篇论‘信任是降低政府/企业成本关键’的文章,无具名真实人物;通用经济/政治观点用 100% 原创行文复述;题材=治理经济学·无害;美语化 labor/organization;第四册第36课·U6收尾课·L32/L33缺源待补)','如果一个国家严重不团结,把它维系在一起的重任就落到政府头上;这既抬高了政府的开支,又相应地减少了本可用于发展国家的经济资源。我们别忘了,在一个贫穷落后的国度里,那点资源是多么微薄。凡是政府开支高的地方,留给发展的资源就相应地少。这个道理,可以拿国家与私营企业作比。企业为了维持经营,不得不承担某些成本;这里我们只关心其中一种——管理和行政这家企业的成本。这类行政管理费,在公司里,好比一个国家的政府开支。它们之所以低,取决于企业里每个人在多大程度上可被信任、能以最有利于公司的方式行事。倘若人人都可被指望在自己的职责范围内担起责任、拿出主动性,那么每个岗位只需一人,管理费便维持在低位。可要是员工没法被这样信任,企业就得雇上成群的管理者、稽核员和工头;随着这些管理费上升,公司在支付了行政成本之后的利润,也随之下降。届时,公司能派作股息、或直接投入自身未来的钱,就更少了。国家也是一模一样。人民在多大程度上可被指望忠诚、负责地行事,政府就在多大程度上无须动用成群的警察与官员去维持秩序。可一旦国家分裂,政府就无法确信人民所为是否合乎国家利益,于是不得不相应地去监视、稽查、管控他们。因此,一个分裂的国家,注定要承担过高的政府开支。','{"q":"Listen and answer — What is the most important factor, both in government and business, for keeping running costs low?","options":["Trust — everyone can be relied upon to behave in the common interest","A large police force","Strict written rules","High wages"],"answer_index":0}'::jsonb,'{"title":"As …, so … / trust·rely on sb to do / to the extent that / can·could be + 过去分词 / Where 引导","intro":"①As … , so …,‘随着…,…也随之…’。②trust/rely on + sb + to do。③to the extent that …,‘在…的程度上’。④can/could/cannot + be + 过去分词(情态与被动连用):can be trusted;could be used。⑤Where 引导从句,‘凡…之处’。","table":{"headers":["用法","结构","例子"],"rows":[["As …, so …","As …, so + 主句","As overheads rise, so earnings fall"],["trust sb to do","trust/rely on + sb + to do","trust each worker to act"],["to the extent that","to the extent that …","low to the extent that all are trusted"],["情态 + 被动","can/could + be + 过去分词","can be trusted; could be used"],["Where 引导","Where …, …","Where the cost is high, resources are low"]]},"specialRules":[{"rule":"As … , so … 表‘随着…而…’的比例关系;后半句用 so 呼应句首的 As。","mark":"As …, so …"},{"rule":"rely 后接介词 on/upon,再接 sb + to do:rely upon the people to behave。","mark":"rely upon sb to do"},{"rule":"美式拼写:labor(劳动,英式 labour)、organization(组织,英式 organisation)。本课已按美语写。","mark":"labor / organization"}]}'::jsonb) ON CONFLICT (id) DO UPDATE SET book_no=EXCLUDED.book_no,title_en=EXCLUDED.title_en,title_cn=EXCLUDED.title_cn,grammar_focus=EXCLUDED.grammar_focus,scene=EXCLUDED.scene,prelisten_question=EXCLUDED.prelisten_question,grammar_card=EXCLUDED.grammar_card;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l36',1,NULL,'If a nation is deeply disunited, it falls to the government to hold it together, and this raises the expense of government while reducing, correspondingly, the economic resources that could be used to develop the country. We should not forget how small those resources are in a poor and backward land. Where the cost of government is high, the resources left for development are correspondingly low.','如果一个国家严重不团结,把它维系在一起的重任就落到政府头上;这既抬高了政府的开支,又相应地减少了本可用于发展国家的经济资源。我们别忘了,在一个贫穷落后的国度里,那点资源是多么微薄。凡是政府开支高的地方,留给发展的资源就相应地少。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l36',2,NULL,'The point may be seen by comparing a nation with a private business. An enterprise has to incur certain costs simply in order to stay in business; here we are concerned with only one of them — the cost of managing and administering the firm. Such administrative overheads are, in a company, analogous to the cost of government in a nation.','这个道理,可以拿国家与私营企业作比。企业为了维持经营,不得不承担某些成本;这里我们只关心其中一种——管理和行政这家企业的成本。这类行政管理费,在公司里,好比一个国家的政府开支。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l36',3,NULL,'They are low to the extent that everyone in the business can be trusted to act in the way that best serves the firm. If each person can be relied upon to take responsibility and to show initiative within his own sphere, then only one worker is needed for each job, and overheads stay low.','它们之所以低,取决于企业里每个人在多大程度上可被信任、能以最有利于公司的方式行事。倘若人人都可被指望在自己的职责范围内担起责任、拿出主动性,那么每个岗位只需一人,管理费便维持在低位。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l36',4,NULL,'But if the workers cannot be trusted in this way, the business will need armies of administrators, checkers, and foremen; and as these administrative overheads rise, so the earnings of the firm, after the cost of administration is met, will fall. The company will then have less money to hand out as dividends or to invest directly in its own future.','可要是员工没法被这样信任,企业就得雇上成群的管理者、稽核员和工头;随着这些管理费上升,公司在支付了行政成本之后的利润,也随之下降。届时,公司能派作股息、或直接投入自身未来的钱,就更少了。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
INSERT INTO public.american_sentences (lesson_id,seq,speaker,text_en,text_cn) VALUES ('am4_l36',5,NULL,'It is exactly the same with a nation. To the extent that the people can be relied upon to behave in a loyal and responsible manner, the government does not need armies of police and officials to keep them in order. But where a nation is disunited, the government cannot be sure that what the people do will serve the nation''s interests, and it must watch, check, and control them accordingly. A disunited nation, therefore, is bound to incur unduly high costs of government.','国家也是一模一样。人民在多大程度上可被指望忠诚、负责地行事,政府就在多大程度上无须动用成群的警察与官员去维持秩序。可一旦国家分裂,政府就无法确信人民所为是否合乎国家利益,于是不得不相应地去监视、稽查、管控他们。因此,一个分裂的国家,注定要承担过高的政府开支。') ON CONFLICT (lesson_id,seq) DO UPDATE SET speaker=EXCLUDED.speaker,text_en=EXCLUDED.text_en,text_cn=EXCLUDED.text_cn;
