INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l36','hold together','',NULL,'/hoʊld təˈɡeðər/','The government must hold the nation together.','政府必须把国家维系在一起。','Glue holds the pieces together.','胶把碎片粘在一起。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l36','rely upon','',NULL,'/rɪˈlaɪ əˈpɑːn/','The firm relies upon its workers to act well.','公司指望员工好好干。','You can rely upon her in a crisis.','危难时你可以指望她。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l36','in order to','',NULL,'/ɪn ˈɔːrdər tuː/','A firm must incur costs in order to stay in business.','企业为维持经营必须承担成本。','They saved in order to buy a house.','他们攒钱为了买房。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_amencontrast (lesson_id,us,uk,note_cn,ipa,example1,example1_cn,example2,example2_cn) VALUES ('am4_l36','be concerned with','',NULL,'/biː kənˈsɜːrnd wɪð/','Here we are concerned only with one kind of cost.','这里我们只关心一种成本。','The book is concerned with trust.','这本书探讨的是信任。') ON CONFLICT (lesson_id,us) DO UPDATE SET ipa=EXCLUDED.ipa,example1=EXCLUDED.example1,example1_cn=EXCLUDED.example1_cn,example2=EXCLUDED.example2,example2_cn=EXCLUDED.example2_cn;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',5,'am4_l36_gp1','choice','{"stem":"\"As overheads rise, ___ the earnings of the business will fall.\"(‘随着…,…也…’,填与句首 As 呼应的那个词)","options":["also","so","then","as"],"answer_index":1,"stem_cn":"随着管理费上升,企业的利润也随之下降。","explanation_cn":"‘随着…,…也随之…’,后半句用 so 呼应句首的 As。✓ As overheads rise, so the earnings fall. ✗ as / then / also:与 As 呼应用 so。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',5,'am4_l36_gp1','choice','{"stem":"\"As the cost of government rises, ___ the resources for development shrink.\"(‘随着…,…也随之…’的呼应结构,填与句首 As 呼应的那个词)","options":["as","and","so","then"],"answer_index":2,"stem_cn":"随着政府开支上升,发展所需的资源也随之缩减。","explanation_cn":"As … , so … 结构,后半用 so 呼应 As。✓ As the cost rises, so the resources shrink. ✗ as / then / and:与 As 呼应用 so。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',5,'am4_l36_gp1','choice','{"stem":"\"As trust grows, ___ the need for checkers falls.\"(‘随着…,…也…’,填与句首 As 呼应的那个词)","options":["then","also","as","so"],"answer_index":3,"stem_cn":"随着信任增加,对监督者的需求也随之减少。","explanation_cn":"As … , so … 结构,后半用 so。✓ As trust grows, so the need for checkers falls. ✗ as / then / also:与 As 呼应用 so。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',5,'am4_l36_gp2','choice','{"stem":"\"The firm can trust each worker ___ act in its interests.\"(trust sb + 不定式,填不定式符号)","options":["of","for","to","at"],"answer_index":2,"stem_cn":"公司可以信任每个员工都为公司利益行事。","explanation_cn":"trust + sb + 不定式;填不定式符号 to。✓ trust each worker to act in its interests. ✗ for / at / of:此结构用 to。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',5,'am4_l36_gp2','choice','{"stem":"\"A government relies on its people ___ behave loyally.\"(rely on sb + 不定式,填不定式符号)","options":["to","in","at","for"],"answer_index":0,"stem_cn":"政府指望国民忠诚守法地行事。","explanation_cn":"rely on + sb + 不定式;填不定式符号 to。✓ rely on its people to behave loyally. ✗ for / at / in:此结构用 to。"}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',5,'am4_l36_gp2','choice','{"stem":"\"If people can be trusted ___ take responsibility, fewer checkers are needed.\"(trust sb + 不定式(被动),填不定式符号)","options":["for","at","to","of"],"answer_index":2,"stem_cn":"若人们可被信任去承担责任,就不需那么多监督者。","explanation_cn":"trust + sb + 不定式(此处被动 can be trusted to do);填不定式符号 to。✓ trusted to take responsibility. ✗ for / at / of:此结构用 to。"}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',5,'am4_l36_gp3','choice','{"stem":"\"Overheads are low ___ the extent that everyone can be trusted.\"(‘在…的程度上’,与 the extent that 搭配的那个介词)","options":["to","in","on","at"],"answer_index":0,"stem_cn":"管理费之低,取决于每个人在多大程度上可被信任。","explanation_cn":"‘在…的程度上’= to the extent that …;与 the extent that 搭配的介词是 to。✓ low to the extent that everyone can be trusted. ✗ in / on / at:此结构用 to。"}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',5,'am4_l36_gp3','choice','{"stem":"\"To the ___ that people behave loyally, less policing is needed.\"(to the … that,‘程度’,填名词)","options":["absence","silence","extent","contrast"],"answer_index":2,"stem_cn":"人们越是忠诚守法,越少需要监管。","explanation_cn":"to the extent that …,‘在…的程度上’;填名词 extent。✓ To the extent that people behave loyally … ✗ contrast / silence / absence:此结构用 extent。"}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',5,'am4_l36_gp3','choice','{"stem":"\"A nation prospers to the extent ___ its people can be relied upon.\"(to the extent + 从句,填连词)","options":["whether","which","what","that"],"answer_index":3,"stem_cn":"一个国家的繁荣,取决于国民在多大程度上可被信赖。","explanation_cn":"to the extent + 从句,引导词用 that。✓ to the extent that its people can be relied upon. ✗ which / what / whether:此结构用 that。"}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',5,'am4_l36_gp4','choice','{"stem":"\"Each worker can be ___ to do his job well.\"(‘能被信任’,can be + 过去分词,填‘信任’那个动词的过去分词)","options":["to trust","trusted","trusting","trust"],"answer_index":1,"stem_cn":"每个工人都能被信任把活儿干好。","explanation_cn":"can be + 过去分词(情态与被动连用),‘能被信任’;填‘信任’那个动词的过去分词 trusted。✓ can be trusted to do his job. ✗ trusting(主动)/ trust / to trust:被动用过去分词。"}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',5,'am4_l36_gp4','choice','{"stem":"\"Resources that could be ___ for development are wasted on control.\"(‘本可被使用’,could be + 过去分词,填‘使用’那个动词的过去分词)","options":["used","to use","using","use"],"answer_index":0,"stem_cn":"本可用于发展的资源,被耗在了管控上。","explanation_cn":"could be + 过去分词,‘本可被使用’;填‘使用’那个动词的过去分词 used。✓ resources that could be used. ✗ using(主动)/ use / to use:被动用过去分词。"}'::jsonb,11) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',5,'am4_l36_gp4','choice','{"stem":"\"The people cannot be ___ upon in a disunited nation.\"(‘不能被指望’,情态词 + be + 过去分词,填‘依赖/指望’那个动词的过去分词)","options":["relying","to rely","rely","relied"],"answer_index":3,"stem_cn":"在一个分裂的国家,人民无法被指望。","explanation_cn":"cannot be + 过去分词,‘不能被指望’;填‘依赖/指望’那个动词的过去分词 relied。✓ cannot be relied upon. ✗ relying(主动)/ rely / to rely:被动用过去分词。"}'::jsonb,12) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',5,'am4_l36_gp5','choice','{"stem":"\"___ the cost of government is high, resources for development are low.\"(‘凡…之处/在…的地方’,填引导词)","options":["Where","What","When","Which"],"answer_index":0,"stem_cn":"凡政府开支高的地方,发展资源就低。","explanation_cn":"‘凡…之处/在…的地方’,用 Where 引导。✓ Where the cost of government is high … ✗ Which / What / When:此处用 Where。"}'::jsonb,13) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',5,'am4_l36_gp5','choice','{"stem":"\"___ people can be trusted, fewer officials are needed.\"(‘凡…之处/在…情况下’,填引导词)","options":["What","Which","Who","Where"],"answer_index":3,"stem_cn":"凡人们可被信任之处,就少需官员。","explanation_cn":"‘凡…之处/在…情况下’,用 Where 引导。✓ Where people can be trusted … ✗ Which / What / Who:此处用 Where。"}'::jsonb,14) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',5,'am4_l36_gp5','choice','{"stem":"\"___ there is no trust, overheads rise sharply.\"(‘凡…之处’,填引导词)","options":["What","Which","Where","Whom"],"answer_index":2,"stem_cn":"凡无信任之处,管理费便急剧上升。","explanation_cn":"‘凡…之处’,用 Where 引导。✓ Where there is no trust … ✗ Which / What / Whom:此处用 Where。"}'::jsonb,15) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',5,'am4_l36_gp6','choice','{"stem":"\"The regular running costs of a business, like rent and management, are its ___.\"(“经常性开支,管理费”用哪个词)","options":["profits","overheads","wages","sales"],"answer_index":1,"stem_cn":"企业的日常运营开支,如租金与管理。","explanation_cn":"企业的经常性运营开支(租金、管理等)是 overheads(管理费)。✓ the regular running costs are overheads. ✗ profits 利润;✗ wages 工资;✗ sales 销售额——都不对。"}'::jsonb,16) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',5,'am4_l36_gp6','choice','{"stem":"\"A share of a company''s profit paid to shareholders is a ___.\"(“股息,红利”用哪个词)","options":["discount","deposit","debt","dividend"],"answer_index":3,"stem_cn":"公司分给股东的一份利润。","explanation_cn":"公司分给股东的一份利润是 dividend(股息、红利)。✓ a share of profit paid to shareholders is a dividend. ✗ deposit 存款;✗ debt 债务;✗ discount 折扣——都不对。"}'::jsonb,17) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',5,'am4_l36_gp6','choice','{"stem":"\"The ability to act and decide on your own is ___.\"(“主动性,首创精神”用哪个词)","options":["initiative","isolation","invitation","imitation"],"answer_index":0,"stem_cn":"自主行动与决断的能力。","explanation_cn":"自主行动与决断的能力是 initiative(主动性)。✓ the ability to act on your own is initiative. ✗ imitation 模仿;✗ invitation 邀请;✗ isolation 孤立——都不对。"}'::jsonb,18) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',6,NULL,'choice','{"stem":"disunited 的意思是:","options":["独立的","繁荣的","团结的","不团结的,分裂的"],"answer_index":3,"explanation_cn":"disunited = 不团结的、分裂的。✓ if a nation is deeply disunited."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',6,NULL,'choice','{"stem":"incur 的意思是:","options":["偿还","减少","招致,承担(费用)","避免"],"answer_index":2,"explanation_cn":"incur = 招致、承担(费用)。✓ an enterprise has to incur certain costs."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',6,NULL,'choice','{"stem":"analogous 的意思是:","options":["无关的","相反的","相等的","类似的,相似的"],"answer_index":3,"explanation_cn":"analogous = 类似的、相似的。✓ analogous to the cost of government."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',6,NULL,'choice','{"stem":"overheads 的意思是:","options":["利润","工资","经常性开支,管理费","税收"],"answer_index":2,"explanation_cn":"overheads = 经常性开支、管理费。✓ administrative overheads stay low."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',6,NULL,'choice','{"stem":"initiative 的意思是:","options":["主动性,首创精神","犹豫","懒惰","服从"],"answer_index":0,"explanation_cn":"initiative = 主动性、首创精神。✓ to show initiative within his sphere."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',6,NULL,'choice','{"stem":"unduly 的意思是:","options":["合理地","过度地,不适当地","适度地","公正地"],"answer_index":1,"explanation_cn":"unduly = 过度地、不适当地。✓ unduly high costs of government."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',7,NULL,'cloze','{"stem":"第 1 空","context":"Administrative overheads are low ___1___ the extent that everyone can be trusted to behave well. If workers can each be ___2___ to take responsibility, fewer checkers are needed. ___3___ trust is missing, the firm must hire armies of administrators. As overheads rise, ___4___ the earnings of the business fall.","blank_no":1,"options":["to","in","on","at"],"answer_index":0,"explanation_cn":"‘在…的程度上’= to the extent that;介词用 to。✓ low to the extent that everyone can be trusted."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',7,NULL,'cloze','{"stem":"第 2 空","context":"Administrative overheads are low ___1___ the extent that everyone can be trusted to behave well. If workers can each be ___2___ to take responsibility, fewer checkers are needed. ___3___ trust is missing, the firm must hire armies of administrators. As overheads rise, ___4___ the earnings of the business fall.","blank_no":2,"options":["trusted","trusting","trust","to trust"],"answer_index":0,"explanation_cn":"trust sb to do 的被动 can be trusted to do;填过去分词 trusted。✓ can each be trusted to take responsibility."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',7,NULL,'cloze','{"stem":"第 3 空","context":"Administrative overheads are low ___1___ the extent that everyone can be trusted to behave well. If workers can each be ___2___ to take responsibility, fewer checkers are needed. ___3___ trust is missing, the firm must hire armies of administrators. As overheads rise, ___4___ the earnings of the business fall.","blank_no":3,"options":["Where","Which","What","When"],"answer_index":0,"explanation_cn":"‘凡…之处’,用 Where 引导。✓ Where trust is missing, the firm must hire administrators."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',7,NULL,'cloze','{"stem":"第 4 空","context":"Administrative overheads are low ___1___ the extent that everyone can be trusted to behave well. If workers can each be ___2___ to take responsibility, fewer checkers are needed. ___3___ trust is missing, the firm must hire armies of administrators. As overheads rise, ___4___ the earnings of the business fall.","blank_no":4,"options":["so","as","then","also"],"answer_index":0,"explanation_cn":"As … , so …,后半用 so 呼应 As。✓ As overheads rise, so the earnings fall."}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET payload=EXCLUDED.payload;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',8,NULL,'choice','{"stem":"What keeps administrative costs low, both in government and business?","options":["Trust — everyone can be relied upon to behave in the common interest","Strict written rules","A large police force","High wages"],"answer_index":0,"explanation_cn":"录音说:无论政府还是企业,压低成本最要紧的是信任——人人都可被指望为共同利益行事。✓ trust as the key factor."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',8,NULL,'choice','{"stem":"What happens to a business when workers cannot be trusted?","options":["It simply closes at once","It needs armies of administrators and checkers, so overheads rise and earnings fall","It becomes more profitable","Its workers leave"],"answer_index":1,"explanation_cn":"录音说:员工不可信任时,企业得雇大量管理者与稽核员,管理费上升、利润下降。✓ overheads rise, earnings fall."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',8,NULL,'choice','{"stem":"Why does a disunited nation have high costs of government?","options":["It has no police at all","Its people are very rich","It spends nothing on development","The government must watch, check, and control people it cannot rely on"],"answer_index":3,"explanation_cn":"录音说:分裂的国家里政府无法信任人民,只得监视、稽查、管控,故成本高。✓ watch, check, control."}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',9,NULL,'choice','{"stem":"你想说\"随着管理费上升,企业的利润也随之下降\"(As … , so …):","options":["As overheads rise, then the earnings of the business fall.","As overheads rise, as the earnings of the business fall.","As overheads rise, so the earnings of the business fall.","So overheads rise, as the earnings of the business fall."],"answer_index":2,"explanation_cn":"As … , so … 表‘随着…而…’;后半用 so 呼应句首 As(不重复用 as、不用 then、也不把 As/So 位置对调)。✓ As …, so … 场合:说“随着…,…也随之…”。"}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',9,NULL,'choice','{"stem":"你想说\"公司可以信任每个员工都为公司利益行事\"(trust sb to do):","options":["The firm can trust each worker to act in its interests.","The firm can trust each worker acting in its interests.","The firm can trust each worker to acting in its interests.","The firm can trust each worker act in its interests."],"answer_index":0,"explanation_cn":"trust + sb + to do;worker 后接 to + 动词原形 act(不省 to、不写 acting、也不写 to acting)。✓ trust each worker to act … 场合:说“信任某人去做…”。"}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',9,NULL,'choice','{"stem":"你想说\"人们越是忠诚守法,越少需要监管\"(to the extent that):","options":["To extent that people behave loyally, less policing is needed.","To the extent that people behave loyally, less policing is needed.","To the extent that people behaving loyally, less policing is needed.","To the extent what people behave loyally, less policing is needed."],"answer_index":1,"explanation_cn":"to the extent that …,‘在…的程度上’;用 that 引导(不用 what)、不能省 the(不写 To extent)、从句用陈述语序 people behave(不写 behaving)。✓ To the extent that … 场合:说“越是…就越…/在…的程度上”。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',10,NULL,'choice','{"stem":"overheads 的意思是:","options":["利润","经常性开支,管理费","工资","税收"],"answer_index":1,"explanation_cn":"overheads = 经常性开支、管理费。✓ administrative overheads stay low."}'::jsonb,1) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',10,NULL,'choice','{"stem":"initiative 的意思是:","options":["懒惰","服从","犹豫","主动性,首创精神"],"answer_index":3,"explanation_cn":"initiative = 主动性、首创精神。✓ to show initiative within his sphere."}'::jsonb,2) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',10,NULL,'choice','{"stem":"\"As overheads rise, ___ the earnings of the business fall.\"(‘随着…,…也…’,填与句首 As 呼应的那个词)","options":["also","so","then","as"],"answer_index":1,"stem_cn":"随着管理费上升,企业利润也随之下降。","explanation_cn":"As … , so …,后半用 so 呼应 As。✓ As overheads rise, so the earnings fall. ✗ as / then / also。"}'::jsonb,3) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',10,NULL,'choice','{"stem":"\"The firm can trust each worker ___ act in its interests.\"(trust sb + 不定式,填不定式符号)","options":["of","for","to","at"],"answer_index":2,"stem_cn":"公司可信任每个员工为公司利益行事。","explanation_cn":"trust + sb + 不定式;填 to。✓ trust each worker to act in its interests. ✗ for / at / of。"}'::jsonb,4) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',10,NULL,'choice','{"stem":"\"rely upon\" 的意思是:","options":["依靠,指望","命令","怀疑","忽视"],"answer_index":0,"explanation_cn":"rely upon = 依靠、指望。✓ the firm relies upon its workers."}'::jsonb,5) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',10,NULL,'choice','{"stem":"\"hold together\" 的意思是:","options":["藏起","拆开","举起","使…团结/不散架"],"answer_index":3,"explanation_cn":"hold together = 使…团结、不散架。✓ the government must hold the nation together."}'::jsonb,6) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',10,NULL,'choice','{"stem":"According to the passage, what makes a business''s administrative overheads low?","options":["The firm sells cheap goods","The workers are paid very little","Everyone can be trusted to act in the firm''s interests, so few supervisors are needed","The business hires many checkers"],"answer_index":2,"passage":"If a nation is deeply disunited, it falls to the government to hold it together, and this raises the expense of government while reducing, correspondingly, the economic resources that could be used to develop the country. We should not forget how small those resources are in a poor and backward land. Where the cost of government is high, the resources left for development are correspondingly low. The point may be seen by comparing a nation with a private business. An enterprise has to incur certain costs simply in order to stay in business; here we are concerned with only one of them — the cost of managing and administering the firm. Such administrative overheads are, in a company, analogous to the cost of government in a nation. They are low to the extent that everyone in the business can be trusted to act in the way that best serves the firm. If each person can be relied upon to take responsibility and to show initiative within his own sphere, then only one worker is needed for each job, and overheads stay low. But if the workers cannot be trusted in this way, the business will need armies of administrators, checkers, and foremen; and as these administrative overheads rise, so the earnings of the firm, after the cost of administration is met, will fall. The company will then have less money to hand out as dividends or to invest directly in its own future. It is exactly the same with a nation. To the extent that the people can be relied upon to behave in a loyal and responsible manner, the government does not need armies of police and officials to keep them in order. But where a nation is disunited, the government cannot be sure that what the people do will serve the nation''s interests, and it must watch, check, and control them accordingly. A disunited nation, therefore, is bound to incur unduly high costs of government.","explanation_cn":"课文说:企业里人人都可被信任、为公司利益行事,便只需极少监督者,管理费就低。✓ trust lowers overheads."}'::jsonb,7) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',10,NULL,'choice','{"stem":"Why does a disunited nation incur high costs of government?","options":["The government cannot trust the people, so it must watch and control them","It has no enemies","Its people are too loyal","Its resources are unlimited"],"answer_index":0,"passage":"If a nation is deeply disunited, it falls to the government to hold it together, and this raises the expense of government while reducing, correspondingly, the economic resources that could be used to develop the country. We should not forget how small those resources are in a poor and backward land. Where the cost of government is high, the resources left for development are correspondingly low. The point may be seen by comparing a nation with a private business. An enterprise has to incur certain costs simply in order to stay in business; here we are concerned with only one of them — the cost of managing and administering the firm. Such administrative overheads are, in a company, analogous to the cost of government in a nation. They are low to the extent that everyone in the business can be trusted to act in the way that best serves the firm. If each person can be relied upon to take responsibility and to show initiative within his own sphere, then only one worker is needed for each job, and overheads stay low. But if the workers cannot be trusted in this way, the business will need armies of administrators, checkers, and foremen; and as these administrative overheads rise, so the earnings of the firm, after the cost of administration is met, will fall. The company will then have less money to hand out as dividends or to invest directly in its own future. It is exactly the same with a nation. To the extent that the people can be relied upon to behave in a loyal and responsible manner, the government does not need armies of police and officials to keep them in order. But where a nation is disunited, the government cannot be sure that what the people do will serve the nation''s interests, and it must watch, check, and control them accordingly. A disunited nation, therefore, is bound to incur unduly high costs of government.","explanation_cn":"课文说:分裂的国家里政府信不过人民,只得监视管控,故政府开支高。✓ cannot trust, must control."}'::jsonb,8) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',10,NULL,'choice','{"stem":"What is the single most important factor for keeping running costs low?","options":["The size of the police force","Whether people can be trusted to behave in the common interest","The level of wages","The number of written rules"],"answer_index":1,"audio":"If a nation is deeply disunited, it falls to the government to hold it together, and this raises the expense of government while reducing, correspondingly, the economic resources that could be used to develop the country. We should not forget how small those resources are in a poor and backward land. Where the cost of government is high, the resources left for development are correspondingly low. The point may be seen by comparing a nation with a private business. An enterprise has to incur certain costs simply in order to stay in business; here we are concerned with only one of them — the cost of managing and administering the firm. Such administrative overheads are, in a company, analogous to the cost of government in a nation. They are low to the extent that everyone in the business can be trusted to act in the way that best serves the firm. If each person can be relied upon to take responsibility and to show initiative within his own sphere, then only one worker is needed for each job, and overheads stay low. But if the workers cannot be trusted in this way, the business will need armies of administrators, checkers, and foremen; and as these administrative overheads rise, so the earnings of the firm, after the cost of administration is met, will fall. The company will then have less money to hand out as dividends or to invest directly in its own future. It is exactly the same with a nation. To the extent that the people can be relied upon to behave in a loyal and responsible manner, the government does not need armies of police and officials to keep them in order. But where a nation is disunited, the government cannot be sure that what the people do will serve the nation''s interests, and it must watch, check, and control them accordingly. A disunited nation, therefore, is bound to incur unduly high costs of government.","explanation_cn":"课文说:压低运营成本最要紧的,是人们能否被信任为共同利益行事。✓ trust is the factor."}'::jsonb,9) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
INSERT INTO public.american_questions (lesson_id,stage,grammar_point_id,qtype,payload,seq) VALUES ('am4_l36',10,NULL,'choice','{"stem":"As administrative overheads rise, what happens to a firm''s earnings?","options":["They stay exactly the same","They rise sharply","They are taxed away","They fall, leaving less to distribute or invest"],"answer_index":3,"audio":"If a nation is deeply disunited, it falls to the government to hold it together, and this raises the expense of government while reducing, correspondingly, the economic resources that could be used to develop the country. We should not forget how small those resources are in a poor and backward land. Where the cost of government is high, the resources left for development are correspondingly low. The point may be seen by comparing a nation with a private business. An enterprise has to incur certain costs simply in order to stay in business; here we are concerned with only one of them — the cost of managing and administering the firm. Such administrative overheads are, in a company, analogous to the cost of government in a nation. They are low to the extent that everyone in the business can be trusted to act in the way that best serves the firm. If each person can be relied upon to take responsibility and to show initiative within his own sphere, then only one worker is needed for each job, and overheads stay low. But if the workers cannot be trusted in this way, the business will need armies of administrators, checkers, and foremen; and as these administrative overheads rise, so the earnings of the firm, after the cost of administration is met, will fall. The company will then have less money to hand out as dividends or to invest directly in its own future. It is exactly the same with a nation. To the extent that the people can be relied upon to behave in a loyal and responsible manner, the government does not need armies of police and officials to keep them in order. But where a nation is disunited, the government cannot be sure that what the people do will serve the nation''s interests, and it must watch, check, and control them accordingly. A disunited nation, therefore, is bound to incur unduly high costs of government.","explanation_cn":"课文说:管理费上升时,企业利润下降,可派股息或再投资的钱就更少。✓ earnings fall."}'::jsonb,10) ON CONFLICT (lesson_id,stage,seq) DO UPDATE SET qtype=EXCLUDED.qtype,payload=EXCLUDED.payload,grammar_point_id=EXCLUDED.grammar_point_id;
